;; int.s:
;;  gg1-1.3p 'maincpu' (Z80)
;;  Z80 interrupt vectors, maincpu.
;; RST_00()
;;  Description:
;;   Z80 reset
;;   Reset/clear the chip command state and jump to the reset handler ($10).
;;   NMI is disabled when  IO_CMD & $0F == 0
;; IN:
;; OUT:
;;  ...
0000: 3E 10                   ld   a,$10            
0002: 32 00 71                ld   ($7100),a        ; [$7100: 06xx control] IO cmd ($10 -> reset/clr chip command state)
0005: C3 C4 02                jp   $02C4            ; -> CPU0_RESET  {jp CPU0_RESET}

;; RST_08()
;;  Description:
;;   HL += 2A
;; IN:
;; OUT:
;;  ...
0008: 87                      add  a,a              
0009: 30 05                   jr   nc,$0010         ; -> rst_HLplusA  {jr nc,rst_HLplusA}
000B: 24                      inc  h                ; add carry into H
000C: C3 10 00                jp   $0010            ; -> rst_HLplusA  {jp rst_HLplusA}
000F: FF                      .db   $FF  ; [rev B]

;; RST_10()
;;  Description:
;;   HL += A
;; IN:
;;   HL
;;   A
;; OUT:
;;   HL
;;   A = L + A
rst_HLplusA:
0010: 85                      add  a,l              
0011: 6F                      ld   l,a              
0012: D0                      ret  nc               
0013: 24                      inc  h                ; add carry into H
0014: C9                      ret                   
0015: FF FF FF                .db   $FF,$FF,$FF  ; [rev B]

;; RST_18()
;;  Description:
;;   memset((HL), A, B)
;; IN:
;;   HL: pointer
;;   A: fill character
;;   B: count
;; OUT:
;;  ...
l_0018:
0018: 77                      ld   (hl),a           
0019: 23                      inc  hl               
001A: 10 FC                   djnz $0018            ; -> l_0018  while (B--)
001C: C9                      ret                   
001D: FF FF FF                .db   $FF,$FF,$FF  ; [rev B]

;; RST_20()
;;  Description:
;;   Quick calculation of DE-=$20
;;   Useful for advancing the "cursor" one character cell to the right on the screen.
;;   Normally called via RST, but in one instance is call'd (jp'd)
;; IN:
;; OUT:
;;  ...
rst_DEminus20:
0020: 7B                      ld   a,e              
0021: D6 20                   sub  $20              
0023: 5F                      ld   e,a              ; result in E
0024: D0                      ret  nc               
0025: 15                      dec  d                ; D gets the carry
0026: C9                      ret                   
0027: FF                      .db   $FF  ; [rev B]

;; RST_28()
;;  Description:
;;   memset(tbl, 0, $F0)
;; IN:
;; OUT:
;;  ...
0028: 21 00 91                ld   hl,$9100         ; {ld hl,#ds_bug_motion_que} memset(..., 0, $F0)
002B: 06 F0                   ld   b,$F0            
002D: AF                      xor  a                ; A==00
002E: DF                      rst  $18              ; memset((HL), A=fill, B=ct)
002F: C9                      ret                   

;; RST_30()
;;  Description:
;;   Entry point to display string function at _139A
;; IN:
;;   If set Cy flag, indicates to _139A to expect a position encoded string
;; OUT:
;;  HL == final offset in video ram (some code actually uses this!)
0030: 37                      scf                   
0031: 08                      ex   af,af'           
0032: C3 B5 13                jp   $13B5            ; -> j_string_out_pe  {jp j_string_out_pe}
0035: FF FF FF                .db   $FF,$FF,$FF  ; [rev B]

;;  Description:
;;   RST $38 handler.
;;   jp to the task manager
;; IN:
;;  ...
;; OUT:
;;  ...
0038: C3 37 02                jp   $0237            ; -> jp_Task_man  {jp jp_Task_man}

