;; NMI
;;  Description:
;;   NMI
;; IN:
;; OUT:
;;  ...
0066: D9                      exx                   ; Load function params from aux regs
0067: ED A0                   ldi                   ; each nmi will move one byte, so BC--, DE++, HL++

;; if ( BC > 0 )  { goto l_008F } ... exit if still copying data
0069: EA 8F 00                jp   pe,$008F         ; -> l_008F  !P/V when BC==0
006C: F5                      push af               ; save AF, it's not part of the exx exchange

;; Signal the chip that the parameter transfer is finished.
006D: 21 00 71                ld   hl,$7100         ; [$7100: 06xx control] $10 - command params complete.
0070: 36 10                   ld   (hl),$10         ; IO_CMD_DONE

;; if ( !player_hit )
0072: 3A B9 9A                ld   a,($9AB9)        ; [$9AB9: 19: !0 ... trigger "bang" sound] sound-fx count/enable registers, ship hit
0075: A7                      and  a                ; A!=0 or maybe 02 when you get hit
0076: 28 16                   jr   z,$008E          ; -> l_plyr_ok  {jr z,l_plyr_ok}

;; else
0078: AF                      xor  a                
0079: 32 B9 9A                ld   ($9AB9),a        ; [$9AB9: 19: !0 ... trigger "bang" sound] 0 ... sound-fx count/enable registers, ship hit
007C: 21 92 00                ld   hl,$0092         ; {ld hl,#d_IO_ChipParms}
007F: 11 00 70                ld   de,$7000         ; [$7000: 06xx data] IO data xfer (write)
0082: 01 04 00                ld   bc,$0004         
0085: D9                      exx                   
0086: 3E A8                   ld   a,$A8            
0088: 32 00 71                ld   ($7100),a        ; [$7100: 06xx control] IO cmd ($A8 -> trigger bang sound)
008B: F1                      pop  af               
008C: ED 45                   retn                  
l_plyr_ok:
008E: F1                      pop  af               
l_008F:
008F: D9                      exx                   ; restore regs for the main "thread"
0090: ED 45                   retn                  ; end 'NMI'

;; data for NMI sub
d_IO_ChipParms:
0092: 10 10 20 20             .db   $10,$10,$20,$20

;; task_man.s
;;  gg1-1.3p 'maincpu' (Z80)
;;  The "task manager" is triggered by the v-blank interrupt (RST 38)
;;  thus the base execution rate is 60Hz. Some tasks will implement
;;  their own sub-rates (e.g. 1 Hz, 4 Hz etc) by checking a global timer.
;;  ds_cpu0_task_actv ($20 bytes) is indexed by order of the
;;  function pointers in d_cpu0_task_table. Periodic tasks can be prioritized,
;;  enabled and disabled by changing the appropriate index in the table.
;;  The task enable table is accessed globally allowing one task to enable or
;;  disable another task. At startup, actv_task_tbl ($20 bytes) is loaded with
;;  a default configuration from ROM.
;;  In ds_cpu0_task_actv the following values are used:
;;   $00 - will skip first entry ($0873) but continue with second
;;   $01
;;   $1f - execute first then skip to last? (but it sets to $00 again?)
;;   $20 - will execute $0873 (empty task) then immediately exit scheduler
;; 00000096  _l_0096                            int0
;; .area ROM (ABS,OVR)
;; .org 0x0096
;; d_cpu0_task_table
;;  Description:
;;   Function pointers to periodic tasks (dispatch table for scheduler)
;;   void (* const d_cpu0_task_table[32])(void)
d_cpu0_task_table:
0096: 27 08                   .db   $27,$08
0098: 28 08                   .db   $28,$08
009A: B2 17                   .db   $B2,$17
009C: 00 17                   .db   $00,$17
009E: 86 1A                   .db   $86,$1A
00A0: 57 08                   .db   $57,$08
00A2: 27 08                   .db   $27,$08
00A4: 27 08                   .db   $27,$08
00A6: 16 29                   .db   $16,$29
00A8: EC 1D                   .db   $EC,$1D
00AA: 90 2A                   .db   $90,$2A
00AC: B9 1D                   .db   $B9,$1D
00AE: DD 23                   .db   $DD,$23
00B0: AA 1E                   .db   $AA,$1E
00B2: 38 1D                   .db   $38,$1D
00B4: 35 09                   .db   $35,$09
00B6: 6B 1B                   .db   $6B,$1B
00B8: B2 19                   .db   $B2,$19
00BA: 7C 1D                   .db   $7C,$1D
00BC: 27 08                   .db   $27,$08
00BE: 8F 1F                   .db   $8F,$1F
00C0: 0E 1F                   .db   $0E,$1F
00C2: 27 08                   .db   $27,$08
00C4: D8 1D                   .db   $D8,$1D
00C6: 22 22                   .db   $22,$22
00C8: CB 21                   .db   $CB,$21
00CA: 27 08                   .db   $27,$08
