;; jp_Task_man()
;;  Description:
;;   handler for rst $38
;;   Updates star control registers.
;;   Executes the Scheduler.
;;   Sets IO chip for control input.
;;   The task enable table is composed of 1-byte entries corresponding to each
;;   of $20 tasks. Each cycle starts at task[0] and advances an index for each
;;   entry in the table. The increment value is actually obtained from the
;;   task_enable table entry itself, which is normally 1, but other values are
;;   also used, such as $20. The "while" logic exits at >$20, so this is used
;;   to exit the task loop without iterating through all $20 entries. Tthe
;;   possible enable values are:
;;     $00 - disables task
;;     $01 - enables task_man
;;     $0A -
;;     $1F -   1F + 0A = $29     (where else could $0A be used?)
;;     $20 - exit current task man step after the currently executed task.
;; IN:
;;  ...
;; OUT:
;;  ...
jp_Task_man:
0237: F5                      push af               
0238: 08                      ex   af,af'           
0239: F5                      push af               
023A: C5                      push bc               
023B: D5                      push de               
023C: E5                      push hl               
023D: DD E5                   push ix               
023F: FD E5                   push iy               

;; determine star_ctrl param bits based on some modulus of frame timer?
;; $A000-$A005 starfield scroll speed (only bit 0 is significant)
0241: 3A 04 68                ld   a,($6804)        ; {ld a,(_sfr_dsw5)} DSWA: freeze video
0244: 57                      ld   d,a              
0245: 3A A0 92                ld   a,($92A0)        ; {ld a,(ds3_92A0_frame_cts + 0)}
0248: E6 1C                   and  $1C              ; 0000XXX0
024A: 4F                      ld   c,a              
024B: 0F                      rrca                  ; 00000XXX
024C: A9                      xor  c                ; A ^ C
024D: E6 18                   and  $18              ; 000XX000
024F: 4F                      ld   c,a              

;; if ( ! freezed_dsw set )
0250: 3A BE 99                ld   a,($99BE)        ; {ld a,(ds_99B9_star_ctrl + 0x05)}
0253: CB 4A                   bit  1,d              ; freeze_ctrl_dsw
0255: 20 02                   jr   nz,$0259         ; -> l_0259

;; else
0257: 3E 07                   ld   a,$07            ; 7==star_ctrl_bits=freezed
l_0259:
0259: E6 07                   and  $07              
025B: B1                      or   c                
025C: 06 05                   ld   b,$05            
025E: 21 00 A0                ld   hl,$A000         ; [$A000: starfield scroll x0] star_ctrl_port
l_0261:
0261: 77                      ld   (hl),a           ; A==star_ctrl_bits
0262: 2C                      inc  l                
0263: 0F                      rrca                  ; star_ctrl_bits >>= 1
0264: 10 FB                   djnz $0261            ; -> l_0261
0266: 32 30 68                ld   ($6830),a        ; {ld (_sfr_watchdog),a}
0269: AF                      xor  a                
026A: 32 20 68                ld   ($6820),a        ; {ld (_sfr_6820),a} 0 ... disable IRQ1

;; if ( freezed )  exit
026D: CB 4A                   bit  1,d              
026F: CA A8 02                jp   z,$02A8          ; -> l_02A8_pop_regs_and_exit  {jp z,l_02A8_pop_regs_and_exit}

;; Execute the Scheduler
0272: 4F                      ld   c,a              ; A == 0 ... initialize index into Task Enable Table

;; while ( 0 == A = *(task_activ_tbl + C) )  C++   ... loop until non-zero: assumes we will find a valid entry in the table!
l_while_index:
l_while_zero:
0273: 21 00 90                ld   hl,$9000         ; {ld hl,#ds_cpu0_task_actv}
0276: 79                      ld   a,c              
0277: 85                      add  a,l              
0278: 6F                      ld   l,a              
0279: 7E                      ld   a,(hl)           ; task_activ_tbl[index]
027A: A7                      and  a                
027B: 20 03                   jr   nz,$0280         ; -> l_0280_nonzero_tbl_entry  {jr nz,l_0280_nonzero_tbl_entry}
027D: 0C                      inc  c                
027E: 18 F3                   jr   $0273            ; -> l_while_index  {jr l_while_zero}

;; save the table entry for later...
l_0280_nonzero_tbl_entry:
0280: 47                      ld   b,a              ; *(task_activ_tbl + C)

;; multiply index 'C' by 2 to form a 16-bit function pointer
;; p_taskfn = d_cpu0_task_table[C]
0281: 21 96 00                ld   hl,$0096         ; {ld hl,#d_cpu0_task_table}
0284: 79                      ld   a,c              ; index
0285: CB 27                   sla  a                ; <<=2 ... sizeof 16-bit function pointer
0287: 85                      add  a,l              
0288: 6F                      ld   l,a              
0289: 5E                      ld   e,(hl)           ; lo-byte of pointer
028A: 23                      inc  hl               
028B: 56                      ld   d,(hl)           ; hi-byte of pointer
028C: EB                      ex   de,hl            ; jp address in HL
028D: C5                      push bc               
028E: CD 3B 00                call $003B            ; -> c_task_switcher  {call c_task_switcher} p_taskfn()
0291: C1                      pop  bc               

;; index+=task_activ_tbl[index]
0292: 78                      ld   a,b              ; *(task_activ_tbl + C)
0293: 81                      add  a,c              ; +=index
0294: 4F                      ld   c,a              

;; while (index < $20)
0295: E6 E0                   and  $E0              ; control values are $00, $01, $20, $1f
0297: 28 DA                   jr   z,$0273          ; -> l_while_index  {jr z,l_while_index}

;; setup regs for input from IO chip
0299: 21 00 70                ld   hl,$7000         ; [$7000: 06xx data] IO data xfer (read)
029C: 11 B5 99                ld   de,$99B5         ; {ld de,#ds3_99B5_io_input + 0x00} read 3 bytes
029F: 01 03 00                ld   bc,$0003         
02A2: D9                      exx                   

;; send command to IO chip
02A3: 3E 71                   ld   a,$71            ; cmd==read ctrl inputs
02A5: 32 00 71                ld   ($7100),a        ; [$7100: 06xx control] IO cmd ($71 -> enable NMI to trigger when data is available)
l_02A8_pop_regs_and_exit:
02A8: 3E 01                   ld   a,$01            
02AA: 32 20 68                ld   ($6820),a        ; {ld (_sfr_6820),a} 1 ... enable IRQ1
02AD: FD E1                   pop  iy               
02AF: DD E1                   pop  ix               
02B1: E1                      pop  hl               
02B2: D1                      pop  de               
02B3: C1                      pop  bc               
02B4: F1                      pop  af               
02B5: 08                      ex   af,af'           
02B6: F1                      pop  af               
02B7: FB                      ei                    
02B8: C9                      ret                   

;; } end 'rst  $0038' handler
d_str20000:
02B9: 00 00 00 00 02 24       .db   $00,$00,$00,$00,$02,$24  ; ; "20000" (reversed)
d_strScore:
02BF: 17 0A 16 0C 18          .db   $17,$0A,$16,$0C,$18  ; ; "SCORE" (reversed)

;; RESET()
;;  Description:
;;   jp here from z80 reset vector
;; IN:
;;  ...
;; OUT:
;;  ...
;; set interrupt mode
CPU0_RESET:
02C4: ED 56                   im   1                

;; memset(mchn_data,0,$10)
02C6: AF                      xor  a                
02C7: 21 E0 99                ld   hl,$99E0         ; {ld hl,#ds10_99E0_mchn_data} clear $10 bytes
02CA: 06 10                   ld   b,$10            
l_02CC:
02CC: 77                      ld   (hl),a           
02CD: 23                      inc  hl               
02CE: 10 FC                   djnz $02CC            ; -> l_02CC

;; let the fun begin!
02D0: C3 6C 33                jp   $336C            ; -> jp_RAM_test  {jp jp_RAM_test}

;; game_ctrl.s:
;;  gg1-1.3p 'maincpu' (Z80)
;;  Manage high-level game control.
;;  j_Game_init:
;;      One time entry from power-up routines.
;;  g_main:
;;      Initializes game state. Starts with Title Screen, or "Press Start"
;;      screen if credit available.
;;  plyr_respawn_splsh:
;;      Sets up each new stage.
;;  jp_045E_While_Game_Run:
;;      Continous loop once the game is started, until gameover.
;;  The possible modes of operation are (from the Bally Manual):
;;    ATTRACT, READY-TO-PLAY, PLAY, HIGH SCORE INITIAL, and SELF-TEST."
;; .area ROM (ABS,OVR)
;; .org 0x02D3
;; por_inits()
;;  Description:
;;   Once per poweron/reset (following hardware inits) do inits for screen and
;;   etc. prior to invoking "main".
;; IN:
;;  ...
;; OUT:
;;  ...
j_Game_init:
