08BE: CB 27                   sla  a                
08C0: CF                      rst  $08              ; HL += 2A
08C1: EB                      ex   de,hl            
08C2: 61                      ld   h,c              
08C3: 3E 0A                   ld   a,$0A            
08C5: CD 61 10                call $1061            ; -> c_divmod  {call c_divmod} HL=HL/10
08C8: EB                      ex   de,hl            ; 8-bit quotient into d ...
08C9: 7A                      ld   a,d              ; ... quotient into a
08CA: D7                      rst  $10              ; HL += A
08CB: 7E                      ld   a,(hl)           
08CC: C9                      ret                   

