;; gg1-2.s
;;  gg1-2.3m, 'maincpu' (Z80)
;;  Utility functions, player and stage setup, text display.
;; .area ROM (ABS,OVR)
;; .org 0x0FFF
;; .db 0x93                                   ; checksum
;; .org 0x1000
;; c_1000()
;;  Description:
;;   for c_25A2
;;   R register used as a randomizer?
;; IN:
;;  ...
;; OUT:
;;   A==random value
;; PRESERVES:
;;   HL
c_1000:
1000: E5                      push hl               
1001: ED 5F                   ld   a,r              
1003: 67                      ld   h,a              
1004: 3A A0 92                ld   a,($92A0)        ; {ld a,(ds3_92A0_frame_cts + 0)}
1007: 84                      add  a,h              
1008: 6F                      ld   l,a              
1009: 26 01                   ld   h,$01            ; {ld h,#>db_obj_home_posn_rc}
100B: 7E                      ld   a,(hl)           
100C: 67                      ld   h,a              
100D: ED 5F                   ld   a,r              
100F: 84                      add  a,h              
1010: E1                      pop  hl               
1011: C9                      ret                   

