;; c_104E_mul_16_8()
;;  Description:
;;   HL := b16 * b8
;; IN:
;;   HL==16 bit factor
;;   A==8 bit factor
;; OUT:
;;   HL=16 bit product
;; SAVES:
;;   DE
c_104E_mul_16_8:
104E: D5                      push de               
104F: EB                      ex   de,hl            
1050: 21 00 00                ld   hl,$0000         
l_1053:
1053: CB 3F                   srl  a                
1055: 30 01                   jr   nc,$1058         ; -> l_1058
1057: 19                      add  hl,de            
l_1058:
1058: CB 23                   sla  e                
105A: CB 12                   rl   d                
105C: A7                      and  a                
105D: 20 F4                   jr   nz,$1053         ; -> l_1053
105F: D1                      pop  de               
1060: C9                      ret                   

;; c_1061()
;;  Description:
;;   Integer division and modulus operation. NOTE input value is NOT preserved.
;;   HL = HL / A
;;    A = HL % A
;;   Uses ADC to sort of left-rotate the Dividend bitwise, linking through Cy
;;   Flag into A and from A through Cy back into HL.
;; IN:
;;  A = Divisor
;;  HL = Dividend
;; OUT:
;;  HL = Quotient
;;  A =  Modulus
;; PRESERVES: BC, DE
c_divmod:
1061: C5                      push bc               
1062: 4F                      ld   c,a              ; keep the divisor in C
1063: AF                      xor  a                
1064: 06 11                   ld   b,$11            ; bit shift counter (pre-increment for djnz)
l_1066:
1066: 8F                      adc  a,a              ; "left shift" the modulus portion and pick up any overflow from HL.
1067: 38 0B                   jr   c,$1074          ; -> l_1074
1069: B9                      cp   c                ; hint: this does a-c
106A: 38 01                   jr   c,$106D          ; -> l_106D  if (a<c )then goto ccf ... (Cy is set and the ccf will clear it)
106C: 91                      sub  c                ; else subtract_divisor ... (Cy is not set, the ccf will set it)
l_106D:
106D: 3F                      ccf                   ; Compliment Cy Flag ... if set then the modulus result has overflowed...
l_106E:
106E: ED 6A                   adc  hl,hl            ; ... and overflow out of modulus result is added to quotient.
1070: 10 F4                   djnz $1066            ; -> l_1066
1072: C1                      pop  bc               
1073: C9                      ret                   
l_1074:
1074: 91                      sub  c                
1075: 37                      scf                   ; need to explicitly set Cy so overflow of A will be summed with result in HL
1076: C3 6E 10                jp   $106E            ; -> l_106E

;; c_1079()
;;  Description:
;;   Called once for each of boss + 1 or 2 wingmen.
;; IN:
;;   HL == &b_8800[n] ... bits 0:6 ... loaded at l_1B8B from boss_wing_slots[n + 0]
;;         if bit-7 set then negate rotation angle to (ix)0x0C
;;         (creature originating on right side)
;;   DE == pointer to object data (in cpu-sub1 code space)
;; OUT:
;;  ...
c_1079:
1079: 7D                      ld   a,l              
107A: E6 80                   and  $80              ; if set then negate rotation angle to (ix)0x0C
107C: 3C                      inc  a                ; set bit-0, .b13<0> makes object slot active
107D: 08                      ex   af,af'           
107E: CB BD                   res  7,l              
1080: C3 8A 10                jp   $108A            ; -> j_108A

;; c_1083()
;;  Description:
;;   Diving movement of red alien, yellow alien, clone-attacker, and rogue fighter.
;; IN:
;;   HL == &b_8800[n]
;;   DE == pointer to object data (in cpu-sub1 code space)
;; OUT:
;;  ...
;; set A:bit-7 if L:bit-1 != 0 ... creature originating on right side
c_1083:
1083: 7D                      ld   a,l              
1084: 0F                      rrca                  
1085: 0F                      rrca                  
1086: E6 80                   and  $80              ; if set then negate rotation angle to (ix)0x0C
1088: 3C                      inc  a                ; set bit-0, .b13<0> makes object slot active
1089: 08                      ex   af,af'           

;; j_108A()
;;  Description:
;;   Setup motion for diving attackers.
;; IN:
;;   HL == &b_8800[n]
;;   DE == pointer to table in cpu-sub1 code space
;;   A' ==
;;        bit-0: set by c_1083 and c_1079
;;        bit-7: flag set for negative rotation angle
;; OUT:
j_108A:
108A: D5                      push de               

;; find an available data structure or quit
108B: 11 14 00                ld   de,$0014         ; size of 1 data structure
108E: 06 0C                   ld   b,$0C            ; number of structures in array
1090: DD 21 00 91             ld   ix,$9100         ; {ld ix,#ds_bug_motion_que}
l_1094:
1094: DD CB 13 46             bit  0,(ix+$13)       ; check for activated state
1098: 28 06                   jr   z,$10A0          ; -> l_10A0_got_one  {jr z,l_10A0_got_one}
109A: DD 19                   add  ix,de            
109C: 10 F6                   djnz $1094            ; -> l_1094
109E: D1                      pop  de               
109F: C9                      ret                   
l_10A0_got_one:
10A0: D1                      pop  de               ; pointer to table
10A1: DD 73 08                ld   (ix+$08),e       ; data pointer lsb
10A4: DD 72 09                ld   (ix+$09),d       ; data pointer msb
10A7: DD 36 0D 01             ld   (ix+$0D),$01     ; expiration counter
10AB: DD 36 04 00             ld   (ix+$04),$00     ; msb, 0x0100 (90 degrees)
10AF: DD 36 05 01             ld   (ix+$05),$01     ; lsb
10B3: 4D                      ld   c,l              ; stash index to obj_status[], sprite etc.
10B4: DD 71 10                ld   (ix+$10),c       ; index of object, sprite etc.
10B7: 08                      ex   af,af'           
10B8: 57                      ld   d,a              ; function parameter from A' to 0x13(ix)
10B9: 36 09                   ld   (hl),$09         ; obj_status[l].state ... disposition = diving attack
10BB: DD 7D                   ld   a,ixl            
10BD: 2C                      inc  l                
10BE: 77                      ld   (hl),a           ; obj_status[L].idx ... index into flying que
10BF: 3A 15 92                ld   a,($9215)        ; {ld a,(b_9215_flip_screen)}
10C2: 5F                      ld   e,a              

;; insert sprite Y coord into pool structure
10C3: 69                      ld   l,c              ; restore index to obj_status[], sprite etc. (dec l just as good, no?)
10C4: 26 93                   ld   h,$93            ; {ld h,#>ds_sprite_posn}
10C6: 4E                      ld   c,(hl)           ; sprite_x
10C7: 2C                      inc  l                
10C8: 46                      ld   b,(hl)           ; sprite_y<7:0>
10C9: 26 9B                   ld   h,$9B            ; {ld h,#>ds_sprite_ctrl}
10CB: 7E                      ld   a,(hl)           ; sprite_y<8>
10CC: 0F                      rrca                  ; sY<8> into Cy
10CD: CB 18                   rr   b                ; sY<8> from Cy to b<7> and sY<0> to Cy
10CF: CB 43                   bit  0,e              ; test flipped screen
10D1: 20 09                   jr   nz,$10DC         ; -> l_10DC

;; not flipped screen
;; 160 - sprite_y + 1 ... backwards math since sY<8:1> already loaded in B, and this is only for flipped screen
