11BA: EB                      ex   de,hl            

;; now HL == tile_ram address  and  DE == div10 and mod10 result
;; offset base pointer in HL by the nbr of tile columns needed:
;; if ( A >= 5 )  { C = A = A - 4 }  ... if mod10 > 5 then only 1 tile for the 5, plus nbr of 1's
