;; sprite_tiles_display()
;;  Description:
;;   Display sprite tiles in specific arrangements loaded from table data.
;;   This is for demo or game-start (bonus-info ) screen but not gameplay.
;; IN:
;;  _attrmode_sptiles: ptr to sprite tiles data
;; OUT:
;;  _attrmode_sptiles: advanced to next data group
c_sprite_tiles_displ:   ; galagao $128C
129E: 26 8B                   ld   h,$8B            ; {ld h,#>ds_sprite_code}

;; L = p_sptiles_displ[idx*4 + 0] ... index/offset of object to use
12A0: ED 5B 80 92             ld   de,($9280)       ; {ld de,(p_attrmode_sptiles)} load the persistent pointer (not always needed)
12A4: 1A                      ld   a,(de)           ; _attrmode_sptiles[ E + 0 ]
12A5: 6F                      ld   l,a              

;; C = p_sptiles_displ[E+1] ... color/code
12A6: 13                      inc  de               ; _attrmode_sptiles[DE].b01  ... color/code
12A7: 1A                      ld   a,(de)           
12A8: 4F                      ld   c,a              

;; sprite_code<3:6>
;; tile 0+6 in each set of 8 is the "upright" orientation (wings spread for bug)
12A9: E6 78                   and  $78              
12AB: C6 06                   add  a,$06            
12AD: 77                      ld   (hl),a           ; sprite_code_base[ object + 0 ] ... sprite tile code

;; advance pointer, i.e. sprite_code_base[ index + 1 ] ... color code
12AE: 2C                      inc  l                

;; get color bits from original color/code value
12AF: 79                      ld   a,c              
12B0: E6 07                   and  $07              

;; Apparently bit-7 of the color/code provides color bit-3
;; if (C & 0x80)  A |= 0x08
12B2: CB 79                   bit  7,c              
12B4: 28 02                   jr   z,$12B8          ; -> l_12A6
12B6: F6 08                   or   $08              
l_12A6:   ; galagao $12A6
12B8: 77                      ld   (hl),a           ; sprite_code_base
12B9: 13                      inc  de               ; &table[ n + 2 ]  ... L/R offset
12BA: 2D                      dec  l                ; object_data[ n + 0 ] ... object state
12BB: 26 88                   ld   h,$88            
12BD: 36 01                   ld   (hl),$01         ; disposition = ACTIVE
12BF: 26 93                   ld   h,$93            ; {ld h,#>ds_sprite_posn}
12C1: 1A                      ld   a,(de)           ; L/R offset
12C2: 77                      ld   (hl),a           ; sprite_posn.X

;; Y coordinate: the table value is actually sprite.posn.Y<8..1> and the sla
;; causes the Cy flag to pick up sprite.posn<8> ...
12C3: 13                      inc  de               ; &table[ n + 3 ]  ... T/B offset
12C4: 2C                      inc  l                ; sprite_posn.Y<0..7>
12C5: 1A                      ld   a,(de)           
12C6: CB 27                   sla  a                
12C8: 77                      ld   (hl),a           ; sprite_posn.Y

;; and sprite.posn<8> is handled here, i.e. ctrl[n + 1]<0>
12C9: 3E 00                   ld   a,$00            ; set the sprite with no additional control attributes
12CB: 17                      rla                   
12CC: 26 9B                   ld   h,$9B            ; {ld h,#>ds_sprite_ctrl}
12CE: 77                      ld   (hl),a           

;; advance the pointer
12CF: 13                      inc  de               ; e.g., DE:=$1960
12D0: ED 53 80 92             ld   ($9280),de       ; {ld (p_attrmode_sptiles),de} += 1
12D4: C9                      ret                   

;; gctl_stg_fmtn_hpos_init()
;;  Description:
;;   plyr_changeover or new_stg_setup, also for start of demo "stage"....after
;;   the rank icons are shown and the text is shown i.e. "game over" or "stage x"
;; IN:
;;   A == offset ... 0 on new-screen, $3F on player changeover
;; OUT:
;;  ...
c_12C3:   ; galagao $12C3
12D5: DD 6F                   ld   ixl,a            
12D7: 3A 15 92                ld   a,($9215)        ; {ld a,(b_9215_flip_screen)}
12DA: 4F                      ld   c,a              

;; init formation location tracking structure: relative (offset) initialize to 0
;; and origin coordinate bits<8:1> from data (copy of origin coordinate from
;; CPU0 data as it would be outside of address space of CPU1)
12DB: 21 00 99                ld   hl,$9900         ; {ld hl,#ds_hpos_loc_t} init home_posn_loc[]
12DE: 11 21 13                ld   de,$1321         ; {ld de,#db_fmtn_hpos_orig}
12E1: 06 10                   ld   b,$10            ; table size
l_12D1:   ; galagao $12D1
12E3: 36 00                   ld   (hl),$00         ; fmtn_hpos.offs[]
12E5: 2C                      inc  l                
12E6: 1A                      ld   a,(de)           
12E7: 13                      inc  de               
12E8: 77                      ld   (hl),a           ; pair.b1 i.e. ds_hpos_loc_orig ... copy data for reference in CPU1
12E9: 2C                      inc  l                
12EA: 10 F7                   djnz $12E3            ; -> l_12D1

;; X coordinates at origin (10 bytes) to even offsets, adjusted for flip-screen.
12EC: 21 00 98                ld   hl,$9800         ; {ld hl,#ds_hpos_spcoords} init origin x-coords (10 columns)
12EF: 11 21 13                ld   de,$1321         ; {ld de,#db_fmtn_hpos_orig}
12F2: 06 0A                   ld   b,$0A            
l_12E2:   ; galagao $12E2
12F4: 1A                      ld   a,(de)           ; home_posn_ini[B]
12F5: 13                      inc  de               
12F6: CB 41                   bit  0,c              ; test if flip_screen
12F8: 28 03                   jr   z,$12FD          ; -> l_12EB
12FA: C6 0D                   add  a,$0D            ; flipped
12FC: 2F                      cpl                   
l_12EB:   ; galagao $12EB
12FD: 77                      ld   (hl),a           ; store lsb
12FE: 2C                      inc  l                
12FF: 2C                      inc  l                ; no msb to store
1300: 10 F2                   djnz $12F4            ; -> l_12E2

;; Y coordinates at origin (6 bytes) to even offsets. Offset argument (in ixl)
;; is added and result adjusted for flip-screen. Only bits <8:1> are stored.
;; For non-inverted screen, equivalent of "$0160 - n" is implemented.
1302: 06 06                   ld   b,$06            
l_12F2:   ; galagao $12F2
1304: 1A                      ld   a,(de)           ; db_fmtn_hpos_orig[B]
1305: DD 85                   add  a,ixl            
1307: 13                      inc  de               
1308: CB 41                   bit  0,c              ; test if flip_screen
130A: 20 03                   jr   nz,$130F         ; -> l_12FD
130C: C6 4F                   add  a,$4F            ; add offset
130E: 2F                      cpl                   ; negate
l_12FD:   ; galagao $12FD
130F: CB 27                   sla  a                ; Cy now contains bit-8
1311: 77                      ld   (hl),a           
1312: 2C                      inc  l                
1313: 3E 00                   ld   a,$00            
1315: 17                      rla                   ; bit-8 from Cy into bit-0 of MSB
1316: 77                      ld   (hl),a           
1317: 2C                      inc  l                
1318: 10 EA                   djnz $1304            ; -> l_12F2
131A: 3A 15 92                ld   a,($9215)        ; {ld a,(b_9215_flip_screen)}
131D: 32 0F 92                ld   ($920F),a        ; {ld (ds_9200_glbls + 0x0F),a} = _flip_screen (nest direction... 1:left, 0:right)
1320: C9                      ret                   

;; Initial pixel coordinates of cylon attackers are copied to odd-offsets of home_posn_loc[].
;;   |<-------------- COLUMNS ------------------------>|<---------- ROWS ----------->|
;;     00   02   04   06   08   0A   0C   0E   10   12   14   16   18   1A   1C   1E
db_fmtn_hpos_orig:   ; galagao $130F
1321: 31 41 51 61 71 81 91 A1 .db   $31,$41,$51,$61,$71,$81,$91,$A1
1329: B1 C1 92 8A 82 7C 76 70 .db   $B1,$C1,$92,$8A,$82,$7C,$76,$70

