;;  Description:
;;   used in game_ctrl
;;   delay 3 count on .5 second timer used various places (in game_ctrl)
;; IN:
;;  ...
;; OUT:
;;  ...
;; PRESERVES:
;;  HL
c_tdelay_3:   ; galagao $131F
1331: E5                      push hl               

;; game_tmrs[3] = 3
1332: 21 AF 92                ld   hl,$92AF         ; {ld hl,#ds4_game_tmrs + 3} =3 ... while ! 0
1335: 36 03                   ld   (hl),$03         

;; while ( game_tmrs[3] != 0 ) {}
l_1325:   ; galagao $1325
1337: 7E                      ld   a,(hl)           
1338: A7                      and  a                
1339: 20 FC                   jr   nz,$1337         ; -> l_1325
133B: E1                      pop  hl               
133C: C9                      ret                   

;; c_player_respawn()
;;  Description:
;;    Single player, shows "player 1", then overwrite w/ "stage 1" and show "player 1" above
;;                            |       PLAYER 1
;;               PLAYER 1     |       STAGE 1
;;                                    PLAYER 1
;;                                    STAGE 1     (S @ 8270)
;;                                    PLAYER 1
;;                                    READY       (R @ 8270)
;;    Get READY to start a new ship, after destroying or capturing the one in play.
;;    ("Player X" text already is shown).
;;    Format is different one plyr vs two.
;;    One Plyr:
;;     Updates "Ready" game message text (except for on new stage...
;;     ..."STAGE X" already shown in that position).
;;    Two Plyr:
;;      Next players nest has already descended onto screen w/ "PLAYER X" text shown.
;;     "Ready" is already shown from somewhere else (05f1).
;;    Removes one ship from reserve. (p_136c)
;;    (used in game_ctrl)
;; IN:
;;  ...
;; OUT:
;;  ...
c_player_respawn:   ; galagao $132B
133D: 3E 01                   ld   a,$01            
133F: 32 14 90                ld   ($9014),a        ; {ld (ds_cpu0_task_actv + 0x14),a} 1  (f_1F85 ... control stick input)

;; check if "STAGE X" text shown and if so skip showing "READY"
;; if ( *(8270) ) == ' ' ) ...
1342: 3A 70 82                ld   a,($8270)        ; {ld a,(m_tile_ram + 0x0260 + 0x10)}
1345: FE 24                   cp   $24              
1347: 20 03                   jr   nz,$134C         ; -> l_133A

;; ... else
1349: 0E 03                   ld   c,$03            ; string_out_pe  index
134B: F7                      rst  $30              ; string_out_pe "READY" (at 8270)

;; c_133A()
;;  Description:
;;   Demo mode (f_17B2) ...
;;   ...while (bug/bee flys home) ...ship hit, waiting for flying bug to re-nest
;;   Label provided for code reuse (jr from c_player_respawn)
;; IN:
;;  ...
;; OUT:
;;  ...
l_133A:   ; galagao $133A
c_133A:   ; galagao $133A
l_133A_while:   ; galagao $133A
134C: 3A 87 92                ld   a,($9287)        ; {ld a,(b_bugs_flying_nbr)}
134F: A7                      and  a                
1350: 20 FA                   jr   nz,$134C         ; -> l_133A  {jr nz,l_133A_while} wait for all bugs to stop flying
1352: CD 7E 13                call $137E            ; -> draw_resv_ships  {call draw_resv_ships} updates reserve ships in lower left corner (wipes CREDIT X)

;; put the ship out there
1355: 21 06 09                ld   hl,$0906         ; two bytes, code 6, color 9
1358: 22 62 8B                ld   ($8B62),hl       ; {ld (ds_sprite_code + 0x62),hl} = $0906 ... ship-1 code 6, color 9 (load 16-bits)
135B: 21 62 93                ld   hl,$9362         ; {ld hl,#ds_sprite_posn + 0x62} ship (1) position

;; if ( !_flip_screen )  A = $29,  C = 1
135E: 3A 15 92                ld   a,($9215)        ; {ld a,(b_9215_flip_screen)}
1361: E6 01                   and  $01              
1363: 3E 29                   ld   a,$29            
1365: 0E 01                   ld   c,$01            
1367: 28 03                   jr   z,$136C          ; -> l_135A

;; else  A = $37,  C = 0
1369: C6 0E                   add  a,$0E            ; screen is flipped in demo?????
136B: 0D                      dec  c                
l_135A:   ; galagao $135A
136C: 36 7A                   ld   (hl),$7A         ; SPRPOSN.0[$62] ... sx
136E: 2C                      inc  l                
136F: 77                      ld   (hl),a           ; SPRPOSN.1[$62] ... sy<0:7>
1370: 26 9B                   ld   h,$9B            ; {ld h,#>ds_sprite_ctrl}
1372: 71                      ld   (hl),c           ; SPRCTRL.1[n]:0 ... sy<8>
1373: 2D                      dec  l                
1374: AF                      xor  a                
1375: 77                      ld   (hl),a           ; 0 ... SPRCTRL.0[n] (no flip/double attribute)
1376: 32 13 92                ld   ($9213),a        ; {ld (ds_9200_glbls + 0x13),a} 0 ... stage restart flag
1379: 3C                      inc  a                
137A: 32 B9 99                ld   ($99B9),a        ; {ld (ds_99B9_star_ctrl + 0),a} 1 ... when ship on screen
137D: C9                      ret                   

;; fghtr_resv_draw()
;;  Description:
;;   Draws up to 6 reserve ships in the status area of the screen, calling
;;   the subroutine 4 times to build the ship icons from 4 tiles.
;; IN:
;;  ...
;; OUT:
;;  ...
draw_resv_ships:   ; galagao $136C
137E: 3A 20 98                ld   a,($9820)        ; {ld a,(ds_plyr_actv +_b_nships)}
1381: 2F                      cpl                   
1382: C6 09                   add  a,$09            ; [rev B]
1384: 5F                      ld   e,a              
1385: 16 49                   ld   d,$49            ; $4A,$4B,$4C,$4D ... / \ [ ]
1387: 21 1D 80                ld   hl,$801D         ; {ld hl,#m_tile_ram + 0x0000 + 0x1D}
138A: CD 98 13                call $1398            ; -> draw_resv_ship_tile  {call draw_resv_ship_tile}
138D: 2D                      dec  l                ; advance 1 column right
138E: CD 98 13                call $1398            ; -> draw_resv_ship_tile  {call draw_resv_ship_tile}
1391: CB ED                   set  5,l              ; +=32 (down 1 row)
1393: 2C                      inc  l                ; 1 column to the left
1394: CD 98 13                call $1398            ; -> draw_resv_ship_tile  {call draw_resv_ship_tile}
1397: 2D                      dec  l                ; advance 1 column right

;; call draw_resv_ship_tile
;; draw_resv_ship_tile()
;;  Description:
;;   Each ship is composed of 4 tiles. This is called once for each tile.
;;   Each tile is replicated at the correct screem offset, allowing up to 6
;;   reserve ship indicators to be shown. Unused locations are filled with
;;   the "space" character tile.
;; IN:
;;   HL: offset in tile ram
;;    D: tile character
;;    E: nr of reserve ships
;; OUT:
;;    D: tile character (increment)
;; PRESERVES:
;;    HL: current offset in tile ram
draw_resv_ship_tile:   ; galagao $1386
1398: E5                      push hl               
1399: 14                      inc  d                
139A: 4A                      ld   c,d              ; [rev B]
139B: 06 08                   ld   b,$08            ; [rev B]
139D: 78                      ld   a,b              ; [rev B]
139E: BB                      cp   e                ; [rev B]
139F: 20 02                   jr   nz,$13A3         ; [rev B]
13A1: 0E 24                   ld   c,$24            ; [rev B]
13A3: 7E                      ld   a,(hl)           ; [rev B]
13A4: FE 36                   cp   $36              ; [rev B]
13A6: 38 04                   jr   c,$13AC          ; [rev B]
13A8: FE 4A                   cp   $4A              ; [rev B]
13AA: 38 01                   jr   c,$13AD          ; [rev B]
13AC: 71                      ld   (hl),c           ; [rev B]
13AD: 2D                      dec  l                ; [rev B]
13AE: 2D                      dec  l                ; [rev B]
13AF: 10 EC                   djnz $139D            ; [rev B]
13B1: E1                      pop  hl               
13B2: C9                      ret                   

;; c_string_out()
;;  Description:
;;    Copy a series of characters to tile-ram (see d_cstring_tbl).
;;    Converts characters strings from ASCII to corresponding character tiles.
;;    Machine character set:
;;     $00 - $09 : decimal digit characters.
;;     $0A - $23 : A-Z
;;     $24       : <space>
;;    String length is variant - the termination token is $2F (ascii "/").
;;    Can be called two ways:
;;    CALL:
;;      Destination position address is passed in HL and swapped into DE.
;;    RST $30:
;;      RST $30 sets the CY flag and JPs to string_out_pe.
;;      The string pointer is then offset (-2) i.e. sizeof(ptr) to get
;;      the destination position address, which winds up in DE.
;;      With the position address in DE, the rest of the routine is the same.
;;  IN:
;;    HL: position in tile RAM.
;;    C: index into table of string pointers (d_cstring_tbl)
;;    CY: "set" if jumped to j_string_out_pe
;;  OUT:
;;    HL contains final string character display position.
;;    PRESERVES :   DE
c_string_out:   ; galagao $1398
13B3: A7                      and  a                ; clear CY flag.
13B4: 08                      ex   af,af'           ; save CY flag.
j_string_out_pe:   ; galagao $139A
13B5: D5                      push de               ; preserves DE
13B6: EB                      ex   de,hl            ; DE := position in tile RAM

;; Get address of string pointer using index in C ...
;; p_sptr = ( ptr_tbl - sizeof(ptr) ) + sizeof(ptr) * index
13B7: 79                      ld   a,c              ; C = index into table string pointers (d_cstring_tbl)
13B8: 21 EF 13                ld   hl,$13EF         ; {ld hl,#d_cstring_tbl - 2} index is ordered from 1 !!
13BB: CF                      rst  $08              ; HL += 2A

;; De-reference the string pointer
;; sptr = *(p_sptr)
13BC: 7E                      ld   a,(hl)           ; lsb
13BD: 23                      inc  hl               
13BE: 66                      ld   h,(hl)           ; msb
13BF: 6F                      ld   l,a              ; lsb

;; Restore flags and check CY
13C0: 08                      ex   af,af'           

;; if ( CY ) ...
13C1: 30 06                   jr   nc,$13C9         ; -> l_13AE

;; ... do PE stuff: get position into DE ... HL-=2, DE:=*(HL)
13C3: 2B                      dec  hl               
13C4: 2B                      dec  hl               
13C5: 5E                      ld   e,(hl)           ; LSB
13C6: 23                      inc  hl               
13C7: 56                      ld   d,(hl)           ; MSB
13C8: 23                      inc  hl               ; HL now pointing to "color".

;; now DE == position, so the rest is the same...
l_13AE:   ; galagao $13AE
13C9: 4E                      ld   c,(hl)           ; C := color byte ($00 == "cyan")
13CA: 23                      inc  hl               ; ptr++ (first byte of "text")
13CB: EB                      ex   de,hl            ; position address in HL, src address in DE

;; if ( TERMINATION ) then exit
l_13B1:   ; galagao $13B1
13CC: 1A                      ld   a,(de)           
13CD: FE 2F                   cp   $2F              ; string terminator
13CF: 28 1E                   jr   z,$13EF          ; -> l_13D4_out  {jr z,l_13D4_out}

;; only a <space> character ($20) should be < $30
13D1: D6 30                   sub  $30              ; e.g. ASCII "0" ... ($30 - $30 ) = 0, "1" ... ($31 - $30 ) = 1 ... etc.
13D3: 30 04                   jr   nc,$13D9         ; -> l_13BE
13D5: 3E 24                   ld   a,$24            ; generate a <space> character.
13D7: 18 06                   jr   $13DF            ; -> l_13C4_putc  {jr l_13C4_putc}

;; if ( A >= $11 )
l_13BE:   ; galagao $13BE
13D9: FE 11                   cp   $11              ; e.g. ASCII "A" ... ($41 - $30) = $11
13DB: 38 02                   jr   c,$13DF          ; -> l_13C4_putc  {jr c,l_13C4_putc}

;; then A-=7
13DD: D6 07                   sub  $07              ; e.g. ASCII "A" ... ($41 - $30 - $07) = $0A
l_13C4_putc:   ; galagao $13C4
13DF: 77                      ld   (hl),a           ; display the character
13E0: CB D4                   set  2,h              ; H |= $04  (HL:+=$0400)  offset HL into color RAM $8400-$87FF
13E2: 71                      ld   (hl),c           ; color code in C
13E3: CB 94                   res  2,h              ; HL:-=$0400
13E5: 13                      inc  de               ; psrc++

;; HL-=$20 (advance destination position one tile to the "right")
13E6: 7D                      ld   a,l              
13E7: D6 20                   sub  $20              
13E9: 6F                      ld   l,a              
13EA: 30 E0                   jr   nc,$13CC         ; -> l_13B1
13EC: 25                      dec  h                
13ED: 18 DD                   jr   $13CC            ; -> l_13B1
l_13D4_out:   ; galagao $13D4
13EF: D1                      pop  de               
13F0: C9                      ret                   

