1C94: CB 4F                   bit  1,a              
1C96: 28 02                   jr   z,$1C9A          ; -> l_1C94
1C98: EE 01                   xor  $01              
l_1C94:   ; galagao $1C94
1C9A: E6 03                   and  $03              
1C9C: CB 27                   sla  a                
1C9E: C6 30                   add  a,$30            ; boss objects are 30 34 36 32
1CA0: 5F                      ld   e,a              ; object/index of bomber to _1CAE
1CA1: 1A                      ld   a,(de)           ; d == #>b_8800
1CA2: FE 01                   cp   $01              ; check for ready/available status
1CA4: C0                      ret  nz               
1CA5: E1                      pop  hl               ; will return to task manager eventually
j_1CA0:   ; galagao $1CA0
1CA6: FD 21 11 04             ld   iy,$0411         ; {ld iy,#db_flv_0411}
1CAA: 3A 0B 92                ld   a,($920B)        ; {ld a,(ds_9200_glbls + 0x0B)} enemy enable, select data ptr boss launch: if (0), iy=$00F1, else iy=$0411
1CAD: A7                      and  a                
1CAE: 20 04                   jr   nz,$1CB4         ; -> l_1CAE  {jr nz,l_1CAE}
1CB0: FD 21 F1 00             ld   iy,$00F1         ; {ld iy,#db_flv_00f1} training-mode

;; setup bomber-boss, _boss_pool[0], bonus scoring, etc.
;; if capture boss (jp $1CAE), paremeters same as above except:
;; IN:
