;; f_1DD2()
;;  Description:
;;   Updates array of 4 timers at 2Hz rate.
;; IN:
;;  ...
;; OUT:
;;  ...
;; if ( frame_cts[2] & 0x01 ) return ... divides the 4 Hz timer by 2 ... why not just use frame_cts[1]
f_1DD2:   ; galagao $1DD2
1DD8: 3A A2 92                ld   a,($92A2)        ; {ld a,(ds3_92A0_frame_cts + 2)} [2]: 4 Hz timer
1DDB: E6 01                   and  $01              
1DDD: C0                      ret  nz               
1DDE: 21 AC 92                ld   hl,$92AC         ; {ld hl,#ds4_game_tmrs + 0} decrement each of the 4 game timers
1DE1: 06 04                   ld   b,$04            

;; for ( b = 0 ; b < 4 ; b++ ) {
;; if ( game_tmrs[b] > 0 )   game_tmrs[b]--
l_1DDD:   ; galagao $1DDD
1DE3: 7E                      ld   a,(hl)           
1DE4: A7                      and  a                
1DE5: 28 01                   jr   z,$1DE8          ; -> l_1DE2
1DE7: 35                      dec  (hl)             
l_1DE2:   ; galagao $1DE2
1DE8: 2C                      inc  l                
1DE9: 10 F8                   djnz $1DE3            ; -> l_1DDD  {djnz l_1DDD}

;; }
1DEB: C9                      ret                   

;; f_1DE6()
;;  Description:
;;   Provides pulsating movement of the collective.
;;   Enabled by f_2A90 once the initial formation waves have completed.
;; IN:
;;  ...
;; OUT:
;;  ...
;; if ( frame_count % 4 != 0 ) return
f_1DE6:   ; galagao $1DE6
1DEC: 3A A0 92                ld   a,($92A0)        ; {ld a,(ds3_92A0_frame_cts + 0)} frame_ct%4 ... ... (provides 15Hz timer)
1DEF: E6 03                   and  $03              
1DF1: C0                      ret  nz               
1DF2: 21 0F 92                ld   hl,$920F         ; {ld hl,#ds_9200_glbls + 0x0F} nest_direction counter for expand/contract motion.
1DF5: 7E                      ld   a,(hl)           
1DF6: 5F                      ld   e,a              ; PREVIOUS_nest_direction counter
1DF7: 16 FF                   ld   d,$FF            
1DF9: CB 7F                   bit  7,a              
1DFB: 20 05                   jr   nz,$1E02         ; -> l_1DFC_contracting  {jr nz,l_1DFC_contracting}

;; expanding
1DFD: 14                      inc  d                
1DFE: 14                      inc  d                
1DFF: 34                      inc  (hl)             ; nest_direction = 1
1E00: 18 01                   jr   $1E03            ; -> l_1DFD  {jr l_1DFD}
l_1DFC_contracting:   ; galagao $1DFC
1E02: 35                      dec  (hl)             ; nest_direction = -1
l_1DFD:   ; galagao $1DFD
1E03: FE 1F                   cp   $1F              ; counting up from $00 to $1F
1E05: 20 02                   jr   nz,$1E09         ; -> l_1E03
1E07: CB FE                   set  7,(hl)           ; count |= $80 ... = $A0
l_1E03:   ; galagao $1E03
1E09: FE 81                   cp   $81              ; counting down from $A0 to $81 (-$60 to -$7F)
1E0B: 20 02                   jr   nz,$1E0F         ; -> l_1E09
1E0D: CB BE                   res  7,(hl)           ; count &= ~$80 ... = $00

;; Now we have updated the counter, and have D==1 if expanding, D==-1 if contracting.
;; Every 8*4 (32) frames, we change the bitmap which determines the positions that are
;; updated. This happens to correspond with the "flapping" animation... ~1/2 second per flap.
l_1E09:   ; galagao $1E09
1E0F: 4E                      ld   c,(hl)           ; grab nest_direction while we still have the pointer
1E10: E6 07                   and  $07              ; previous_cntr % 8
1E12: 7A                      ld   a,d              ; direction counter increment (+1 or -1)
1E13: 32 11 92                ld   ($9211),a        ; {ld (ds_9200_glbls + 0x11),a} formatn_mv_signage, cpu2 cp with b_9A80 + 0x00
1E16: 7B                      ld   a,e              ; reload previous_nest_direction counter

;; if ( previous_counter % 8 == 0 ) then update_bitmap i.e. even multiple of 8
1E17: 20 10                   jr   nz,$1E29         ; -> l_1E23
1E19: 21 6A 1E                ld   hl,$1E6A         ; {ld hl,#d_1E64_bitmap_tables}

;; count * 2 i.e. count / 8 * 16 ... index into table row
1E1C: 79                      ld   a,c              ; A = updated_counter
1E1D: E6 18                   and  $18              ; make it even multiple of 8
1E1F: CF                      rst  $08              ; HL += 2A   .... table entries are $10 bytes long
1E20: 7B                      ld   a,e              ; reload previous_nest_direction counter
1E21: 11 20 99                ld   de,$9920         ; [ds10_9920] $10 bytes copied from 1E64+2*A
1E24: 01 10 00                ld   bc,$0010         
1E27: ED B0                   ldir                  

;; A ^= (HL) ... set Cy determines which parameter is taken. Bit-7 XOR'd with
;; flip_screen-bit... done efficiently by rotating bit-7 into bit-0 and back.
l_1E23:   ; galagao $1E23
1E29: 21 15 92                ld   hl,$9215         ; {ld hl,#b_9215_flip_screen}
1E2C: 07                      rlca                  ; A == previous_counter
1E2D: AE                      xor  (hl)             
1E2E: 0F                      rrca                  ; Cy now indicates state of bit-7

;; Setup parameters for first function call. The first call does just the
;; left-most 5 columns. The second call does the rightmost 5 columns and the
;; 6 row coordinates, which incidentally will have the same sign! So we stash
;; the parameter for the second call in C, at the same time that B is set.
1E2F: 21 20 99                ld   hl,$9920         ; [ds10_9920] 16 bytes copied from _bitmap_tables+2*A
1E32: 11 00 99                ld   de,$9900         ; {ld de,#ds_hpos_loc_offs} hl==ds10_9920
1E35: 30 05                   jr   nc,$1E3C         ; -> l_1E36
1E37: 01 FF 01                ld   bc,$01FF         ; B==1, C==-1 (contracting group, non-inverted)
1E3A: 18 03                   jr   $1E3F            ; -> l_1E39
l_1E36:   ; galagao $1E36
1E3C: 01 01 FF                ld   bc,$FF01         ; {ld bc,#0xFF01} B==-1, C==1 (expanding group, non-inverted)
l_1E39:   ; galagao $1E39
1E3F: DD 2E 05                ld   ixl,$05          ; {ld ixl,#5} 5 leftmost columns
1E42: CD 49 1E                call $1E49            ; -> c_1E43

;; setup parameters for second function call
1E45: 41                      ld   b,c              ; load second parameter
1E46: DD 2E 0B                ld   ixl,$0B          ; {ld ixl,0x0b} 5 right columns + 6 rows

;; 1E43()
;; c_1E43()
;;  Description:
;;   Compute row/col coordinates of formation in expand/contract movement.
;;   The selected bitmap table determines whether any given coordinate
;;   dimension is incremented at this update.
;; IN:
;;    HL == saved pointer into working copy of selected bitmap table ($10 bytes)
;;    DE == saved pointer into home_posn_loc[]
;;        ... object positioning (even: relative offsets .... odd: defaults/origin)
;;    B == +/- 1 increment.
;;    IXL == 5  (repeat count for 5 leftmost columns)
;;    IXL == 11 (repeat count, for 5 rightmost columns + 6 rows which have the same sign)
;; OUT:
;;  ...
;; check if updating this one
c_1E43:   ; galagao $1E43
j_1E43:   ; galagao $1E43
1E49: CB 0E                   rrc  (hl)             
1E4B: 30 15                   jr   nc,$1E62         ; -> l_1E5C_update_ptrs  {jr nc,l_1E5C_update_ptrs}

;; obj_pos_rel[ n ] += B
1E4D: 1A                      ld   a,(de)           ; even-bytes: relative offset
1E4E: 80                      add  a,b              ; +/- 1
1E4F: 12                      ld   (de),a           

;; _home_posn_org[ n ] += B ... 10 column coordinates, 6 row coordinates, 16-bits per coordinate
1E50: 16 98                   ld   d,$98            ; {ld d,#>ds_hpos_spcoords}
1E52: 1A                      ld   a,(de)           
1E53: 80                      add  a,b              ; +/- 1
1E54: 12                      ld   (de),a           

;; check for carry
1E55: 1F                      rra                   
1E56: A8                      xor  b                
1E57: 07                      rlca                  
1E58: 30 06                   jr   nc,$1E60         ; -> l_1E5A

;; handle carry
1E5A: 1C                      inc  e                
1E5B: 1A                      ld   a,(de)           ; MSB
1E5C: EE 01                   xor  $01              
1E5E: 12                      ld   (de),a           
1E5F: 1D                      dec  e                ; LSB again
l_1E5A:   ; galagao $1E5A
1E60: 16 99                   ld   d,$99            ; {ld d,#>ds_hpos_loc_offs} reset pointer
l_1E5C_update_ptrs:   ; galagao $1E5C
1E62: 1C                      inc  e                
1E63: 1C                      inc  e                
1E64: 2C                      inc  l                
1E65: DD 2D                   dec  ixl              
1E67: 20 E0                   jr   nz,$1E49         ; -> c_1E43
1E69: C9                      ret                   

;; d_1E64_bitmap_tables
;;  Description:
;;   bitmaps determine at which intervals the corresponding coordinate will
;;   be incremented... allows outmost and lowest coordinates to expand faster.
;;      |<-------------- COLUMNS --------------------->|<---------- ROWS ---------->|
d_1E64_bitmap_tables:   ; galagao $1E64
1E6A: FF 77 55 14 10 10 14 55 .db   $FF,$77,$55,$14,$10,$10,$14,$55
1E72: 77 FF 00 10 14 55 77 FF .db   $77,$FF,$00,$10,$14,$55,$77,$FF
1E7A: FF 77 55 51 10 10 51 55 .db   $FF,$77,$55,$51,$10,$10,$51,$55
1E82: 77 FF 00 10 51 55 77 FF .db   $77,$FF,$00,$10,$51,$55,$77,$FF
1E8A: FF 77 57 15 10 10 15 57 .db   $FF,$77,$57,$15,$10,$10,$15,$57
1E92: 77 FF 00 10 15 57 77 FF .db   $77,$FF,$00,$10,$15,$57,$77,$FF
1E9A: FF F7 D5 91 10 10 91 D5 .db   $FF,$F7,$D5,$91,$10,$10,$91,$D5
1EA2: F7 FF 00 10 91 D5 F7 FF .db   $F7,$FF,$00,$10,$91,$D5,$F7,$FF

;; f_1EA4()
;;  Description:
;;    Bomb position updater... this task is not disabled.
;; IN:
;;  ...
;; OUT:
;;  ...
;; Determine y-increment: each frame alternates 2 or 3 pixels-per-frame
;; increment to provide the average Y velocity, and negated for inverted screen.
f_1EA4:   ; galagao $1EA4
1EAA: 3A A0 92                ld   a,($92A0)        ; {ld a,(ds3_92A0_frame_cts + 0)}
1EAD: E6 01                   and  $01              
1EAF: C6 02                   add  a,$02            
1EB1: 47                      ld   b,a              
1EB2: 3A 15 92                ld   a,($9215)        ; {ld a,(b_9215_flip_screen)}
1EB5: A7                      and  a                
1EB6: 78                      ld   a,b              
1EB7: 28 02                   jr   z,$1EBB          ; -> l_1EB5
1EB9: ED 44                   neg                   
l_1EB5:   ; galagao $1EB5
1EBB: DD 67                   ld   ixh,a            
1EBD: 2E 68                   ld   l,$68            ; offset into object group for missiles
1EBF: 11 B0 92                ld   de,$92B0         ; [b_92B0: bomb X-rate] bomb h-rate array ( 8 * 2 )
1EC2: DD 2E 08                ld   ixl,$08          ; {ld ixl,0x08}

;; if sprite[bomb + n].code == $30 ...
l_1EBF_while:   ; galagao $1EBF
1EC5: 26 8B                   ld   h,$8B            ; {ld h,#>ds_sprite_code}
1EC7: 7E                      ld   a,(hl)           
1EC8: FE 30                   cp   $30              ; bomb sprite codes don't show up until some new-game inits are done
1ECA: 20 39                   jr   nz,$1F05         ; {jr nz,l_1EFF}

;; ... sprite[bomb + n].posn.x != 0
1ECC: 26 93                   ld   h,$93            ; {ld h,#>ds_sprite_posn}
1ECE: 7E                      ld   a,(hl)           
1ECF: A7                      and  a                
1ED0: 28 33                   jr   z,$1F05          ; {jr z,l_1EFF}

;; Fun fixed point math: X rate in 92B0[ even ] has a scale factor of
;; 32-counts -> 1 pixel-per-frame. Each frame, the (unchanging) dividend
;; is loaded from 92B0, the previous MOD32 is added, the new MOD32 is stashed
;; in 92B1, and the quotient becomes the new X-offset. Eventually those
;; remainders add up to another whole divisor which will add an extra pixel
;; to the offset every nth frame. Easy peasy!
;; BTW there really is odd values in 92B0, but we just seem to not care about it i.e. mask 7E.
1ED2: EB                      ex   de,hl            ; stash &sprite_posn[n].b0 in DE
1ED3: 46                      ld   b,(hl)           ; bomb_rate[n].b0
1ED4: 78                      ld   a,b              
1ED5: E6 7E                   and  $7E              ; Bit-7 for negative ... and we don't want the 1 ???
1ED7: 2C                      inc  l                
1ED8: 86                      add  a,(hl)           
1ED9: 4F                      ld   c,a              ; C = A = A + 92B0[odd] ... accumulated division remainder
1EDA: E6 1F                   and  $1F              ; MOD 32
1EDC: 77                      ld   (hl),a           ; bomb_rate[n].b1
1EDD: 2C                      inc  l                

;; a >>= 5 (divide-by-32)
1EDE: 79                      ld   a,c              
1EDF: 07                      rlca                  
1EE0: 07                      rlca                  
1EE1: 07                      rlca                  
1EE2: E6 07                   and  $07              

;; use negative offset of X coordinate if bomb path is to the left
1EE4: CB 78                   bit  7,b              
1EE6: 28 02                   jr   z,$1EEA          ; -> l_1EE4
1EE8: ED 44                   neg                   
l_1EE4:   ; galagao $1EE4
1EEA: EB                      ex   de,hl            ; &sprite_posn[n].b0 from DE

;; update X
1EEB: 86                      add  a,(hl)           
1EEC: 77                      ld   (hl),a           ; 9868[ even ] += A

;; update Y, and handle Cy for value > $ff
1EED: 2C                      inc  l                
1EEE: 7E                      ld   a,(hl)           
1EEF: DD 84                   add  a,ixh            
1EF1: 77                      ld   (hl),a           ; sprite[n].y<7:0> += ixh
1EF2: 1F                      rra                   ; shifts CY into bit-7 on overflow from addition
1EF3: DD AC                   xor  ixh              
1EF5: 07                      rlca                  ; Cy xor'd with ixh<7> ... to Cy
1EF6: 30 07                   jr   nc,$1EFF         ; -> l_1EF9

;; update "bit-8" of Y coordinate ... should only overflow the Y coordinate once.
1EF8: 26 9B                   ld   h,$9B            ; {ld h,#>ds_sprite_ctrl} sY<8>
1EFA: CB 0E                   rrc  (hl)             ; sY<8> into Cy
1EFC: 3F                      ccf                   
1EFD: CB 16                   rl   (hl)             ; sY<8>
l_1EF9:   ; galagao $1EF9
1EFF: 2C                      inc  l                
1F00: DD 2D                   dec  ixl              
1F02: 20 C1                   jr   nz,$1EC5         ; -> l_1EBF_while  {jr nz,l_1EBF_while}
1F04: C9                      ret                   
1F05: 26 88                   ld   h,$88            ; [rev B]
1F07: 36 80                   ld   (hl),$80         ; [rev B]
l_1EFF:   ; galagao $1EFF
1F09: 2C                      inc  l                
1F0A: 1C                      inc  e                
1F0B: 1C                      inc  e                
1F0C: 18 F1                   jr   $1EFF            ; -> l_1EF9

;; f_1F04()
;;  Description:
;;   Read fire button input.
;;   The IO port is determined according to whether or not the screen is flipped.
;;   The button state is read from bit-4. Based on observation in the MAME
;;   debugger, it appears that the IO control chip initially places the value
;;   $1F on the port (bit-5 pulled low), and then some time following that bit-4
;;   is pulled low ($0F). Presumably this is provide a debounce feature. If
;;   there is no activity on either the button or the left-right control, then
;;   the value read from the port is $3F.
;; IN:
;;  ...
;; OUT:
;;  ...
;; select the input port depending upon whether screen is flipped.
f_1F04:   ; galagao $1F04
1F0E: 3A 15 92                ld   a,($9215)        ; {ld a,(b_9215_flip_screen)}
1F11: C6 B6                   add  a,$B6            ; {add a,#<ds3_99B5_io_input + 0x01} add lsb
1F13: 6F                      ld   l,a              
1F14: 26 99                   ld   h,$99            ; {ld h,#>ds3_99B5_io_input + 0x00} msb
1F16: CB 66                   bit  4,(hl)           
1F18: C0                      ret  nz               ; active low input

;; else
;; call c_1F0F
;; c_1F0F()
;;  Description:
;;   Intialize sprite objects for rockets.
;;   rocket sprite.cclr[n].b0 is initialized by c_game_or_demo_init
;;   Updates game shots fired count.
;; IN:
;;  ...
;; OUT:
;;  ...
;; if ( 0 != sprite[ RCKT0 ].sX ) ...
c_1F0F:   ; galagao $1F0F
1F19: 21 64 93                ld   hl,$9364         ; {ld hl,#ds_sprite_posn + 0x64} ROCKET_0
1F1C: 11 A4 92                ld   de,$92A4         ; [$92A4: each byte tracks a shot from the ship] rockt_attribute[0]
1F1F: AF                      xor  a                
1F20: BE                      cp   (hl)             ; if (0)
1F21: 28 05                   jr   z,$1F28          ; -> l_1F1E

;; ... then ... if ( 0 != sprite[ RCKT1 ].sX )  return
1F23: 2E 66                   ld   l,$66            ; {ld l,#<ds_sprite_posn + 0x66} ROCKET_1
1F25: 1C                      inc  e                ; rockt_attribute[1]
1F26: BE                      cp   (hl)             ; if (0 != sprite[RCKT1].sX)  ret
1F27: C0                      ret  nz               

;; save pointer to attribute, and stash 'offsetof( RCKT_X )' in E
l_1F1E:   ; galagao $1F1E
1F28: D5                      push de               ; &rockt_attribute[n].posn.b0
1F29: EB                      ex   de,hl            
1F2A: 21 63 9B                ld   hl,$9B63         ; {ld hl,#ds_sprite_ctrl + 0x62 + 1} sprite.ctrl[FIGHTR].b1
1F2D: 54                      ld   d,h              
1F2E: 1C                      inc  e                ; sprite[RCKT_X].ctrl.b1
