;; else ( A >= 2 ) then .. code = $31
1F59: 0C                      inc  c                ; code $31 ... 45 degree rotation
1F5A: FE 02                   cp   $02              
1F5C: 30 02                   jr   nc,$1F60         ; -> l_1F56_set_rocket_sprite_code  {jr nc,l_1F56_set_rocket_sprite_code}

;; else  ... code = $33
1F5E: 0C                      inc  c                ; code $32 is skipped (also 360)
1F5F: 0C                      inc  c                ; code $33 ... 90 degree rotation
l_1F56_set_rocket_sprite_code:   ; galagao $1F56
1F60: 71                      ld   (hl),c           

;; Displacement in both X and Y axis must be computed in order to launch rockets
;; from the spinning ship. The "primary" axis of travel is whichever one the
;; ship is more closely aligned with and is assigned the maximum displacement
;; value of 6.
;; If the code is 4 thru 6, sY is the primary axis of motion (norm
;; for non-rotated ship), indicated by setting the orientation bit (+ $40).
;; dX in the secondary axis is determined by the sprite rotation (code)
;; as shown in the table below, where the displacement ranges from 0 (ship
;; rotated 90 * n) to a maximum amount of 3 as the ship approaches a rotation
;; of primary+45.
;; See c_0704_update_rockets in cpu1.
;; code= 6     dS=0      $40     ... 7 - (6+1)
;; code= 5     dS=1      $40     ... 7 - (5+1)
;; code= 4     dS=2      $40     ... 7 - (4+1)
;; code= 3     dS=3      $00
;; code= 2     dS=2      $00
;; code= 1     dS=1      $00
;; code= 0     dS=0      $00
;; if ( A >= 4 ) ...
1F61: FE 04                   cp   $04              ; A == sprite.cclr[SHIP].b0;
1F63: 38 03                   jr   c,$1F68          ; -> l_1F5E

;; ... dS = 7 - ( code + 1 ) + 0x40
1F65: 2F                      cpl                   
1F66: C6 47                   add  a,$47            

;; else ... no orientation swap needed, use sprite code for dS
l_1F5E:   ; galagao $1F5E
1F68: CB 27                   sla  a                ; "orientation" bit into bit-7 ...
1F6A: 4F                      ld   c,a              ; ... and displacement << 1  into bits 1:2

;; sprite.ctrl bits ...  flipx into bit:5, flipy into bit:6
1F6B: 78                      ld   a,b              ; sprite.ctrl[SHIP].b0
1F6C: 0F                      rrca                  
1F6D: 0F                      rrca                  
1F6E: 0F                      rrca                  
1F6F: E6 60                   and  $60              ; mask of rotated SPRCTRL[0]:0 and SPRCTRL[0]:1 bits
1F71: 47                      ld   b,a              
1F72: 3A 15 92                ld   a,($9215)        ; {ld a,(b_9215_flip_screen)}
1F75: A7                      and  a                
1F76: 78                      ld   a,b              ; flipx/flipy bits (0x60)
