;; call c_1F92
;; c_1F92()
;;  Description:
;;   Skip real IO input in the demo.
;;   The dX.flag determines the movement step (dX): when the ship movement
;;   direction is changed, dX is 1 pixel increment for 1 frame and then 2 pixel
;;   step thereafter as long as the control stick is held continously to the
;;   direction. If the stick input is neutral, dX.flag (b_92A0[3]) is cleared.
;;   In a two-ship configuration, the position is handled with respect to the
;;   left ship... the right limit gets special handling accordingly.
;; IN:
;;   A == IO input control bits
;;        2 ---> R
;;        8 ---> L
;;   E == actv_plyr_state[7]  .... double ship flag
;; OUT:
;;  ...
;; if ( ( A & 0x0A ) == $0A ... inputs are active low, neither left or right active
c_1F92:   ; galagao $1F92
1F9C: E6 0A                   and  $0A              
1F9E: FE 0A                   cp   $0A              
1FA0: 28 37                   jr   z,$1FD9          ; -> l_1FCF_no_input  {jr z,l_1FCF_no_input}

;; invert the input bits if screen flipped (swap L/R direction)
1FA2: 21 15 92                ld   hl,$9215         ; {ld hl,#b_9215_flip_screen}
1FA5: CB 46                   bit  0,(hl)           
1FA7: 28 02                   jr   z,$1FAB          ; -> l_1FA1_set_ship_dx  {jr z,l_1FA1_set_ship_dx}
1FA9: EE 0A                   xor  $0A              ; screen is flipped

;; set ship.dX (1 or 2)
l_1FA1_set_ship_dx:   ; galagao $1FA1
1FAB: 21 A3 92                ld   hl,$92A3         ; [$92A3: ship.dX_flag] ship_dX_flag
1FAE: 47                      ld   b,a              ; stash the control input bits
1FAF: 0E 01                   ld   c,$01            ; ship_dX = 1

;; toggle ship_dX_flag
1FB1: 7E                      ld   a,(hl)           
1FB2: EE 01                   xor  $01              
1FB4: 77                      ld   (hl),a           ; dX.flag ^= 1

;; if (0 == ship_dX_flag) ship_dX++
1FB5: 20 01                   jr   nz,$1FB8         ; -> l_1FAE_handle_input_bits  {jr nz,l_1FAE_handle_input_bits}
1FB7: 0C                      inc  c                

;; if ( ship.posn.x == 0 ) return
l_1FAE_handle_input_bits:   ; galagao $1FAE
1FB8: 21 62 93                ld   hl,$9362         ; {ld hl,#ds_sprite_posn + 0x62} "main" ship (single) position
1FBB: 7E                      ld   a,(hl)           
1FBC: A7                      and  a                
1FBD: C8                      ret  z                

;; if ( input.Right ) ...
1FBE: CB 48                   bit  1,b              ; if ( ! input bits.right ) ... inverted
1FC0: 20 0F                   jr   nz,$1FD1         ; -> l_1FC7_test_llmt  {jr nz,l_1FC7_test_llmt}

;; if ( ship.posn.x > 0xD1) ... moving right: check right limit for double-ship
1FC2: 7E                      ld   a,(hl)           
1FC3: FE D1                   cp   $D1              ; right limit, double-ship
1FC5: 38 03                   jr   c,$1FCA          ; -> l_1FC0_test_rlmt_single  {jr c,l_1FC0_test_rlmt_single}

;; else if ( double_ship ) return
1FC7: CB 43                   bit  0,e              ; if ( is_double_ship & 0x01 )
1FC9: C0                      ret  nz               ; at right limit of double-ship

;; if ( ship.posn.x >= 0xE1 ) return
l_1FC0_test_rlmt_single:   ; galagao $1FC0
1FCA: FE E1                   cp   $E1              ; right limit, single-ship
1FCC: D0                      ret  nc               

;; add dX for right direction
1FCD: 81                      add  a,c              ; fighter dX
1FCE: 77                      ld   (hl),a           
1FCF: 18 0D                   jr   $1FDE            ; -> l_1FD4_update_two_ship  {jr l_1FD4_update_two_ship}

;; ... else ... test left limit
;; if ( ship.posn.x < 0x12 ) return
l_1FC7_test_llmt:   ; galagao $1FC7
1FD1: 7E                      ld   a,(hl)           
1FD2: FE 12                   cp   $12              ; left limit
1FD4: D8                      ret  c                

;; else
1FD5: 91                      sub  c                ; subtract dX
1FD6: 77                      ld   (hl),a           
1FD7: 18 05                   jr   $1FDE            ; -> l_1FD4_update_two_ship  {jr l_1FD4_update_two_ship}
l_1FCF_no_input:   ; galagao $1FCF
1FD9: AF                      xor  a                
1FDA: 32 A3 92                ld   ($92A3),a        ; [$92A3: ship.dX_flag] ship_dX_flag = 0
1FDD: C9                      ret                   

;; if ( ! two_ship_plyr )  return
l_1FD4_update_two_ship:   ; galagao $1FD4
1FDE: CB 43                   bit  0,e              
1FE0: C8                      ret  z                

;; else ... ship2.posn.x = ship1.posn.x + $0F
1FE1: C6 0F                   add  a,$0F            ; +single ship position
1FE3: 32 60 93                ld   ($9360),a        ; {ld (ds_sprite_posn + 0x60), a} double ship position
1FE6: C9                      ret                   
