1FEF: FF FF FF FF FF FF FF FF .db   $FF,$FF,$FF,$FF,$FF,$FF,$FF,$FF  ; [rev B]
1FF7: FF FF FF FF FF FF FF FF .db   $FF,$FF,$FF,$FF,$FF,$FF,$FF,$FF  ; [rev B]
1FFF: B6                      .db   $B6  ; [rev B]

