25B5: 3C                      inc  a                
25B6: E6 03                   and  $03              
25B8: 28 19                   jr   z,$25D3          ; -> l_25D3_is_challg_stg  {jr z,l_25D3_is_challg_stg}

;; ... then ...
;; HL = &idx_tbl[ rank * 17 ][ 0 ] ... select index table row, by rank
25BA: 3A 84 99                ld   a,($9984)        ; {ld a,(b_mchn_cfg_rank)}
25BD: 2E 11                   ld   l,$11            
25BF: CD 4E 10                call $104E            ; -> c_104E_mul_16_8  {call c_104E_mul_16_8} L = rank * 17
