;; c_2896()
;;  Description:
;;   stg_init_env
;;   Called at beginning of each stage, including challenge stages and demo.
;;   Initializes mrw_sprite[n].cclr.b0 for 3 sets of creatures. Color code is
;;   packed into b<0:2>, and bomb-drop parameter packed into b<7>
;;   Load attributes for challenge stage hit-8 bonus.
;;   Default sprite code configuration:
;;    00 00 00 00 00 00 00 00 18 00 18 00 18 00 18 00
;;    18 00 18 00 18 00 18 00 18 00 18 00 18 00 18 00
;;    18 00 18 00 18 00 18 00 18 00 18 00 18 00 18 00
;;    08 00 08 00 08 00 08 00 00 00 00 00 00 00 00 00
;;    10 00 10 00 10 00 10 00 10 00 10 00 10 00 10 00
;;    10 00 10 00 10 00 10 00 10 00 10 00 10 00 10 00
;;    00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00
;;    00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00
;;   Called before c_25A2.
;; IN:
;;  ...
;; OUT:
;;  ...
;; once per stage, set the player's private pointer to attack wave object setup tables
c_2896:
2896: 21 20 89                ld   hl,$8920         ; {ld hl,#ds_8920} -> plyr_actv.p_atkwav_tbl
2899: 22 22 98                ld   ($9822),hl       ; {ld (ds_plyr_actv +_p_atkwav_tbl),hl} = &ds_8920[0] ... initialize it

;; pointer to table of packed bits set in b<7>  ... see code leading up to _29AE
289C: FD 21 08 29             ld   iy,$2908         

;; if ( 0 == not_chllng_stg ) ...
28A0: 3A 25 98                ld   a,($9825)        ; {ld a,(ds_plyr_actv +_b_not_chllg_stg)} ==(stg_ctr+1)%4 ...i.e. 0 if challenge stage
28A3: A7                      and  a                
28A4: 20 27                   jr   nz,$28CD         ; -> l_28CD_not_challenge_stage  {jr nz,l_28CD_not_challenge_stage}

;; ...
28A6: 3A 21 98                ld   a,($9821)        ; {ld a,(ds_plyr_actv +_b_stgctr)} stage init sprite codes
28A9: 0F                      rrca                  
28AA: 0F                      rrca                  
28AB: 4F                      ld   c,a              ; table index (below)
28AC: 0F                      rrca                  
28AD: 47                      ld   b,a              
28AE: E6 1C                   and  $1C              ; 0x1C ... test if stage >= 32
28B0: 78                      ld   a,b              ; .stage_ctr >> 3
28B1: 28 02                   jr   z,$28B5          ; -> l_28B5
28B3: 3E 03                   ld   a,$03            ; select index 3 if stage >= 32
l_28B5:
28B5: E6 03                   and  $03              ; 4 entries in data (every 8 challenge stages the selection index is stepped)
28B7: 21 00 29                ld   hl,$2900         ; {ld hl,#d_stage_chllg_rnd_attrib}
28BA: CF                      rst  $08              ; HL += 2A
28BB: 11 84 92                ld   de,$9284         ; {ld de,#ds2_stg_chllg_rnd_attrib} challenge bonus attributes (2 bytes from 2900[])
28BE: 79                      ld   a,c              
28BF: ED A0                   ldi                   ; "LD (DE),(HL)", DE++, HL++, BC--
28C1: ED A0                   ldi                   
28C3: 21 0E 29                ld   hl,$290E         ; 8 entries
28C6: E6 07                   and  $07              
28C8: D7                      rst  $10              ; HL += A
28C9: 56                      ld   d,(hl)           
28CA: 5A                      ld   e,d              
28CB: 18 03                   jr   $28D0            ; -> l_28D0

;; Initialization values are base-code + 2 bits of color table.
;; 0x1B = 0x18 + 0x03
;; 0x08 = 0x08 + 0x00
;; 0x12 = 0x10 + 0x02
;; left shift codes by 1 bit because the flag (bit-7) will be rra'd from Cy
;; Results in 3-bits of color (multiple of 2)
l_28CD_not_challenge_stage:
28CD: 11 24 36                ld   de,$3624         
l_28D0:
28D0: 21 08 8B                ld   hl,$8B08         ; {ld hl,#ds_sprite_code + 0x08} offsetof first bee in the group
28D3: DD 2E 01                ld   ixl,$01          ; {ld ixl,#1} start count for bit shifting
28D6: 06 14                   ld   b,$14            ; 20 bees ... $08-$2E
28D8: DD 62                   ld   ixh,d            ; D == moth == $18 | $03
28DA: CD E9 28                call $28E9            ; -> c_28E9
28DD: 06 08                   ld   b,$08            ; 8 bosses and bonus-bees ... $30-$3E
28DF: DD 26 10                ld   ixh,$10          ; {ld ixh,#(0x08 + 0x0) * 2} code      == $08 | $00
28E2: CD E9 28                call $28E9            ; -> c_28E9
28E5: 06 10                   ld   b,$10            ; 16 moths ... $40-$5E
28E7: DD 63                   ld   ixh,e            ; E == bee  == $10 | $02

;; call c_28E9
;; c_28E9()
;;  Description:
;;    Initialize a class of creatures.
;; IN:
;;  B == number of creatures in this class
;;  HL == sprite_code_buf[ $08 + ? ]
;;  IY == &d_2908[0], etc.
;;  IXL == persistent count of bits shifted off of IY[ n++ ]
;;  IXH == $36 or $10 or $24
;; OUT:
;;  ...
;; First time, IXL==1, forcing C to be loaded.
;; After that, reload C every 8 times.
;; Each time, C is RL'd into Cy, and Cy RR'd into A.
;; if ( --IXL == 0 )
c_28E9:
l_28E9:
28E9: DD 2D                   dec  ixl              
28EB: 20 08                   jr   nz,$28F5         ; -> l_28F5

;; then ...  C = IY[ n++ ], IXL = 8
28ED: FD 4E 00                ld   c,(iy+$00)       
28F0: FD 23                   inc  iy               
28F2: DD 2E 08                ld   ixl,$08          ; {ld ixl,#8}
l_28F5:
28F5: CB 01                   rlc  c                
28F7: DD 7C                   ld   a,ixh            ; base sprite-code parameter
28F9: 1F                      rra                   
28FA: 77                      ld   (hl),a           
28FB: 2C                      inc  l                
28FC: 2C                      inc  l                
28FD: 10 EA                   djnz $28E9            ; -> c_28E9
28FF: C9                      ret                   

;; setup challenge stage bonus attributes at l_28B5 (b_9280 + 0x04)
