;; (base-score multiples are * 10 thanks to d_scoreman_inc_lut[0])
d_stage_chllg_rnd_attrib:
2900: 0A B8                   .db   $0A,$B8
2902: 0F B9                   .db   $0F,$B9
2904: 14 BC                   .db   $14,$BC
2906: 1E BD                   .db   $1E,$BD
d_2908:
2908: A5 5A A9 0F 0A 50       .db   $A5,$5A,$A9,$0F,$0A,$50  ; 44-bits used
d_290E:
290E: 36 24 D4 BA E4 CC A8 F4 .db   $36,$24,$D4,$BA,$E4,$CC,$A8,$F4

;; f_2916()
;;  Description:
;;   Inserts creature objects from the attack wave table into the movement
;;   queue. Essentially, it launches the attack formations swarming into the
;;   screen. The table of attack wave structures is built in c_25A2.
;;   Each struct starts with $7E, and the end of table marker is $7F.
;;   This task will be enabled by stg_init_env... after the
;;   creature classes and formation tables are initialized.
;; IN:
;;  ...
;; OUT:
;;  ...
;; check for end of table
;; if ( 7f == current_token ) goto complete
f_2916:
2916: 2A 22 98                ld   hl,($9822)       ; {ld hl,(ds_plyr_actv +_p_atkwav_tbl)} &ds_8920[n]
2919: 7E                      ld   a,(hl)           
291A: FE 7F                   cp   $7F              
291C: CA 29 2A                jp   z,$2A29          ; -> l_2A29_attack_waves_complete  {jp z,l_2A29_attack_waves_complete}

;; check for start of table structure
;; if ( 7e == token ) then .... else .... goto _next_pair
291F: FE 7E                   cp   $7E              
2921: 20 30                   jr   nz,$2953         ; -> l_2953_next_pair  {jr nz,l_2953_next_pair}

;; if ( ! _attack_wave_enable ) return
2923: 3A 42 98                ld   a,($9842)        ; {ld a,(ds_plyr_actv +_b_atk_wv_enbl)} 0 if restarting the stage (respawning player ship)
2926: A7                      and  a                
2927: C8                      ret  z                

;; if ( 0 != bugs_flying_nbr ) goto _set_tmr0
2928: 3A 87 92                ld   a,($9287)        ; {ld a,(b_bugs_flying_nbr)}
292B: A7                      and  a                
292C: 20 1F                   jr   nz,$294D         ; -> l_294D_set_tmr0  {jr nz,l_294D_set_tmr0}

;; if ( 0 == not_challenge_stg ) ...
292E: 3A 25 98                ld   a,($9825)        ; {ld a,(ds_plyr_actv +_b_not_chllg_stg)} ==(stg_ctr+1)%4 ...i.e. 0 if challenge stage
2931: 47                      ld   b,a              ; this does nothing ;)
2932: A7                      and  a                
2933: 20 0F                   jr   nz,$2944         ; -> l_2944_attack_wave_start  {jr nz,l_2944_attack_wave_start}

;; ...
;; if ( 1 == game_tmrs[0] ) ..
2935: 3A AC 92                ld   a,($92AC)        ; {ld a,(ds4_game_tmrs + 0)} if tmr==1 ( on stage 3 ..challenge stage)
2938: FE 01                   cp   $01              
293A: 20 06                   jr   nz,$2942         ; -> l_2942_chk_tmr0  {jr nz,l_2942_chk_tmr0}

;; ..
293C: 3E 08                   ld   a,$08            
293E: 32 A8 92                ld   ($92A8),a        ; {ld (w_bug_flying_hit_cnt),a} 8 ... count down each flying bug hit
2941: C9                      ret                   

;; ..
;; if ( 0 != game_tmrs[0] ) return
l_2942_chk_tmr0:
2942: A7                      and  a                ; game_tmr0
2943: C0                      ret  nz               

;; ...
;; Finally... sending out next wave of creatures. We are on start token 7E so do nothing on this time step.
l_2944_attack_wave_start:
2944: 23                      inc  hl               
2945: 22 22 98                ld   ($9822),hl       ; {ld (ds_plyr_actv +_p_atkwav_tbl),hl} +=1 (first element of byte-pair following the 7e)
2948: 21 26 98                ld   hl,$9826         ; {ld hl,#ds_plyr_actv +_b_attkwv_ctr} +=1
294B: 34                      inc  (hl)             
294C: C9                      ret                   
l_294D_set_tmr0:
294D: 3E 02                   ld   a,$02            
294F: 32 AC 92                ld   ($92AC),a        ; {ld (ds4_game_tmrs + 0),a} 2
2952: C9                      ret                   

;; ....
;; finally, next token-pair !
l_2953_next_pair:
2953: 4F                      ld   c,a              ; *.p_atkwav_tbl ... stash for later

;; bit-7 is set if this toaster is a wing-man or a split waves, and therefore no delay,
;; otherwise it is clear for trailing formation i.e. delay before launching.
;; if ( 0 == *.p_atkwav_tbl & 0x80 ) ...
2954: CB 7F                   bit  7,a              
2956: 20 06                   jr   nz,$295E         ; -> l_295E

;; then ...
2958: 3A A0 92                ld   a,($92A0)        ; {ld a,(ds3_92A0_frame_cts + 0)}
295B: E6 07                   and  $07              
295D: C0                      ret  nz               

;; ready to stick another bug in the flying queue
;; make byte offset into lut at db_2A3C  (_finalize_object) ... also we're done with bit-7
l_295E:
295E: CB 21                   sla  c                

;; find a slot in the queue
2960: 06 0C                   ld   b,$0C            ; number of structures in array
2962: 11 14 00                ld   de,$0014         ; size of 1 data structure
2965: DD 21 00 91             ld   ix,$9100         ; {ld ix,#ds_bug_motion_que}
l_2969_while:
2969: DD CB 13 46             bit  0,(ix+$13)       
296D: 28 05                   jr   z,$2974          ; -> l_2974_got_slot  {jr z,l_2974_got_slot}
296F: DD 19                   add  ix,de            ; advance pointer
2971: 10 F6                   djnz $2969            ; -> l_2969_while  {djnz l_2969_while}
2973: C9                      ret                   ; can't find a slot... bummer

;; each time is another bug of a new wave formation getting ready to appear
l_2974_got_slot:
2974: 23                      inc  hl               
2975: 7E                      ld   a,(hl)           ; atkwav_tbl[n].pair.h ... object ID/offset, e.g. 58
2976: 47                      ld   b,a              ; stash it

;; if object >= $78  &&  object < $80 ) ...
2977: E6 78                   and  $78              
2979: FE 78                   cp   $78              
297B: 78                      ld   a,b              
297C: 20 02                   jr   nz,$2980         ; -> l_2980

;; ...  then ...
297E: CB B7                   res  6,a              ; what object is > $78?
l_2980:
2980: DD 77 10                ld   (ix+$10),a       ; object index
2983: 23                      inc  hl               
2984: 22 22 98                ld   ($9822),hl       ; {ld (ds_plyr_actv +_p_atkwav_tbl),hl} advance to next token-pair e.g. HL:=8923
2987: 26 88                   ld   h,$88            
2989: 6F                      ld   l,a              
298A: 36 07                   ld   (hl),$07         ; 8800[L].l ... disposition = "spawning" ... i.e. case_2590

;; store the slot index (offset) for this object
298C: 2C                      inc  l                
298D: DD 5D                   ld   e,ixl            
298F: 73                      ld   (hl),e           ; 8800[L].h ... offset of slot (n*$14)
2990: 26 93                   ld   h,$93            ; {ld h,#>ds_sprite_posn}

;; if ( object >= $38 && object < $40 ) then goto _setup_transients
2992: E6 38                   and  $38              
2994: FE 38                   cp   $38              
2996: 28 1B                   jr   z,$29B3          ; -> l_29B3_setup_transients  {jr z,l_29B3_setup_transients}

;; else ...
;; Init routine c_2896 has populated the sprite code buffer such that each even
;; byte consists of the "primary" code (multiple of 8), AND'd with the color.
2998: 2D                      dec  l                ; e.g. HL=9358
2999: 26 8B                   ld   h,$8B            ; {ld h,#>ds_sprite_code} sprite[L].code.b0 &= 0x78
299B: 7E                      ld   a,(hl)           
299C: 57                      ld   d,a              ; stash it
299D: E6 78                   and  $78              ; base sprite code for this object (multiple of 8)
299F: 77                      ld   (hl),a           ; sprite[n].cclr.b0
29A0: 2C                      inc  l                ; .b1
29A1: 7A                      ld   a,d              
29A2: E6 07                   and  $07              ; color table in bits <0:2>
29A4: CB 7A                   bit  7,d              
29A6: 77                      ld   (hl),a           ; sprite[n].cclr.b1

;; if ( ! code_bit_7 )
29A7: 3E 00                   ld   a,$00            
29A9: 28 03                   jr   z,$29AE          ; -> l_29AE

;; else
29AB: 3A E3 92                ld   a,($92E3)        ; [$92E3: _stg_dat[1] e.g. *(26F5) ... c_25A2, ld to 0x0f(ix)] to 0x0F(ix) ... _stg_dat[1] ... bomb drop enable flags
l_29AE:
29AE: DD 77 0F                ld   (ix+$0F),a       ; 0, or b_92E2[1] ... bomb drop enable flags
29B1: 18 1E                   jr   $29D1            ; -> l_29D1_finalize_object_setup  {jr l_29D1_finalize_object_setup}

;; handle the additional "transient" buggers that fly-in but don't join ... Stage 4 or higher.
l_29B3_setup_transients:
29B3: 11 10 02                ld   de,$0210         ; redmoth, color 02, 270-deg rotation
29B6: CB 70                   bit  6,b              
29B8: 20 0D                   jr   nz,$29C7         ; -> l_29C7
29BA: 11 18 03                ld   de,$0318         ; yellowbee, color 03, 270-deg rotation
29BD: 3A 26 98                ld   a,($9826)        ; {ld a,(ds_plyr_actv +_b_attkwv_ctr)}
29C0: FE 02                   cp   $02              
29C2: 20 03                   jr   nz,$29C7         ; -> l_29C7
29C4: 11 08 00                ld   de,$0008         ; boss, color 00, 270-deg rotation (>=stage 9)
l_29C7:
29C7: 26 8B                   ld   h,$8B            ; {ld h,#>ds_sprite_code}
29C9: 72                      ld   (hl),d           ; color, e.g. 8B3B=$03
29CA: 2D                      dec  l                
29CB: 73                      ld   (hl),e           ; color, e.g. 8B3A=$18
29CC: 2C                      inc  l                
29CD: DD 36 0F 00             ld   (ix+$0F),$00     ; setup transients ... bomb drop enable flags
l_29D1_finalize_object_setup:
29D1: 51                      ld   d,c              ; first byte of token-pair, left-shifted 1 (byte-1 of _stg_dat triplet)
29D2: CB B9                   res  7,c              
29D4: 06 08                   ld   b,$08            ; critters that enter at the top

;; if ( C & 0x02 ) ...
29D6: CB 49                   bit  1,c              
29D8: 28 02                   jr   z,$29DC          ; -> l_29DC

;; then ...
29DA: 06 44                   ld   b,$44            ; critters that enter on the sides
l_29DC:
29DC: DD 70 0E                ld   (ix+$0E),b       ; $08 or $44 ... bomb drop counter

;; ds_bug_move_queue[IX].b08 = db_2A3C[C] ... LSB of data pointer
29DF: 06 00                   ld   b,$00            
29E1: 21 3C 2A                ld   hl,$2A3C         ; {ld hl,#db_2A3C}
29E4: 09                      add  hl,bc            ; only C is significant
29E5: 7E                      ld   a,(hl)           
29E6: 23                      inc  hl               
29E7: DD 77 08                ld   (ix+$08),a       ; lo-byte of pointer e.g. cpu-sub1:001D

;; get upper nibble of word at db_2A3C[w] (bits 5:7 will be masked by 0x0E below)
;; rld (hl): Performs a 4-bit leftward rotation of the 12-bit number whose
;; 4 most signigifcant bits are the 4 least significant bits of A
29EA: AF                      xor  a                
29EB: ED 6F                   rld                   
29ED: 47                      ld   b,a              

;; ds_bug_move_queue[IX].b09  = db_2A3C[C + 1] & 0x1F ... MSB of data pointer
29EE: 7E                      ld   a,(hl)           
29EF: E6 1F                   and  $1F              
29F1: DD 77 09                ld   (ix+$09),a       ; hi-byte of pointer e.g. cpu-sub1:001D

;; ... get upper 4-bits of word at db_2A3C[w] which were rld'd into A: these
;; are $2 thru $A even, and this is multiplied by 3 by the expression A*2+A
29F4: 78                      ld   a,b              
29F5: E6 0E                   and  $0E              ; bits 5:7 of db_2A3C[].b1
29F7: 47                      ld   b,a              
29F8: 07                      rlca                  
29F9: 80                      add  a,b              
29FA: 21 6C 2A                ld   hl,$2A6C         ; {ld hl,#db_2A6C}
29FD: D7                      rst  $10              ; HL += A

;; D is b0 of byte-pair (left shifted 1, so in _stg_dat it is 0x40)
;; if ( D & 0x80 )
29FE: CB 7A                   bit  7,d              ; 29FE
2A00: 28 03                   jr   z,$2A05          ; -> l_2A05

;; ... then ... HL += 3 ... selects the second set of 3 bytes
2A02: 23                      inc  hl               
2A03: 23                      inc  hl               
2A04: 23                      inc  hl               
l_2A05:
2A05: 7E                      ld   a,(hl)           
2A06: 23                      inc  hl               
2A07: DD 77 01                ld   (ix+$01),a       ; db_2A6C[L].b0
2A0A: 7E                      ld   a,(hl)           
2A0B: 23                      inc  hl               
2A0C: DD 77 03                ld   (ix+$03),a       ; db_2A6C[L].b1
2A0F: 7E                      ld   a,(hl)           
2A10: 23                      inc  hl               
2A11: DD 77 05                ld   (ix+$05),a       ; db_2A6C[L].b2
2A14: AF                      xor  a                
2A15: DD 77 00                ld   (ix+$00),a       ; 0
2A18: DD 77 02                ld   (ix+$02),a       ; 0
2A1B: DD 77 04                ld   (ix+$04),a       ; 0
2A1E: 3C                      inc  a                
2A1F: DD 77 0D                ld   (ix+$0D),a       ; 1 ... expiration counter
2A22: B2                      or   d                ; 1st byte of current byte-pair (left shifted 1, so in _stg_dat it is 0x40)
2A23: E6 81                   and  $81              ; .b13<7> negates rotation angle
2A25: DD 77 13                ld   (ix+$13),a       ; A &= $81 ... .b13<0> makes object slot active
2A28: C9                      ret                   

;; all 8 of the last wave of bees are on screen now... waiting for them to get in position.
;; if (nbr_flying bugs > 0 ) return
l_2A29_attack_waves_complete:
2A29: 3A 87 92                ld   a,($9287)        ; {ld a,(b_bugs_flying_nbr)}
2A2C: A7                      and  a                
2A2D: C0                      ret  nz               

;; the last one has found its position in the collective.
2A2E: 32 08 90                ld   ($9008),a        ; {ld (ds_cpu0_task_actv + 0x08),a} 0  (f_2916 ... end of attack waves)
2A31: 3C                      inc  a                
2A32: 32 04 90                ld   ($9004),a        ; {ld (ds_cpu0_task_actv + 0x04),a} 1  (f_1A80 ... bonus-bee manager)
2A35: 32 10 90                ld   ($9010),a        ; {ld (ds_cpu0_task_actv + 0x10),a} 1  (f_1B65 ... manage bomber attack )
2A38: 32 24 98                ld   ($9824),a        ; {ld (ds_plyr_actv +_b_nestlr_inh),a} 1  ... inhibit nest left/right movement
2A3B: C9                      ret                   

;; bits 0:12  - pointer to data tables for flying pattern control.
;; bits 13:15 - selection index into lut 2A6C.
db_2A3C:
2A3C: 1D 00 67 20 9F 40 D4 20 .db   $1D,$00,$67,$20,$9F,$40,$D4,$20
2A44: 7B 01 B0 61 E8 01 F5 21 .db   $7B,$01,$B0,$61,$E8,$01,$F5,$21
2A4C: 0B 02 1B 22 2B 82 41 22 .db   $0B,$02,$1B,$22,$2B,$82,$41,$22
2A54: 5D 82 79 22 9E 02 BA 22 .db   $5D,$82,$79,$22,$9E,$02,$BA,$22
2A5C: D9 02 FB 22 1D 03 33 23 .db   $D9,$02,$FB,$22,$1D,$03,$33,$23
2A64: DA 0F F0 2F 2B A2 5D A2 .db   $DA,$0F,$F0,$2F,$2B,$A2,$5D,$A2

;; bits 13:15 from above provide bits<1:3> of the index
;; bit-6 of _stg_dat provide bits<1> of the index (second set of 3-bytes in each pair)
;; (ix)0x01 (ix)0x03 (ix)0x05
db_2A6C:
2A6C: 9B 34 03                .db   $9B,$34,$03  ; 0
2A6F: 9B 44 03                .db   $9B,$44,$03
2A72: 23 00 00                .db   $23,$00,$00  ; 2
2A75: 23 78 02                .db   $23,$78,$02
2A78: 9B 2C 03                .db   $9B,$2C,$03  ; 4
2A7B: 9B 4C 03                .db   $9B,$4C,$03
2A7E: 2B 00 00                .db   $2B,$00,$00  ; 6
2A81: 2B 78 02                .db   $2B,$78,$02
2A84: 9B 34 03                .db   $9B,$34,$03  ; 8
2A87: 9B 34 03                .db   $9B,$34,$03
2A8A: 9B 44 03                .db   $9B,$44,$03  ; A
2A8D: 9B 44 03                .db   $9B,$44,$03

;; f_2A90()
;;  Description:
;;   left/right movement of collective while attack waves coming in at
;;   start of round.
;; IN:
;;  ...
;; OUT:
;;  ...
;; if ( frame_cnt % 4 != 0 ) return
f_2A90:
2A90: 3A A0 92                ld   a,($92A0)        ; {ld a,(ds3_92A0_frame_cts + 0)}
2A93: 3D                      dec  a                ; why -1 ?
2A94: E6 03                   and  $03              
2A96: C0                      ret  nz               

;; check for exit condition
;; if  ! ( num_bugs != 0  ||  f_2916_active )  then ...
2A97: 3A A7 92                ld   a,($92A7)        ; {ld a,(b_bugs_actv_nbr)}
2A9A: 47                      ld   b,a              
2A9B: 3A 08 90                ld   a,($9008)        ; {ld a,(ds_cpu0_task_actv + 0x08)} f_2916 supervises attack waves
2A9E: B0                      or   b                
2A9F: 28 48                   jr   z,$2AE9          ; -> l_2AE9_done  {jr z,l_2AE9_done}

;; if ( 0 == nest_dir_lr ) then C = 1,  else C = -1
2AA1: 3A 0F 92                ld   a,($920F)        ; {ld a,(ds_9200_glbls + 0x0F)} nest direction... 1==left, 0==right
2AA4: A7                      and  a                
2AA5: 0E 01                   ld   c,$01            
2AA7: 28 02                   jr   z,$2AAB          ; -> l_2AAB  {jr z,l_2AAB}
2AA9: 0D                      dec  c                
2AAA: 0D                      dec  c                ; C = -1

;; initialize index and loop counter, update the table
l_2AAB:
2AAB: 2E 00                   ld   l,$00            ; index into table
2AAD: 06 0A                   ld   b,$0A            ; nbr of column positions

;; increment the relative position
l_2AAF:
2AAF: 26 99                   ld   h,$99            ; {ld h,#>ds_hpos_loc_offs} even-bytes, relative offset, all 0's, then all 1's, etc. etc.
2AB1: 7E                      ld   a,(hl)           
2AB2: 81                      add  a,c              ; +1 or -1
2AB3: 77                      ld   (hl),a           

;; increment sprite position LSB
2AB4: 26 98                   ld   h,$98            ; {ld h,#>ds_hpos_spcoords}
2AB6: 7E                      ld   a,(hl)           
2AB7: 81                      add  a,c              
2AB8: 77                      ld   (hl),a           

;; HL+=2
2AB9: 2C                      inc  l                
2ABA: 2C                      inc  l                
2ABB: 10 F2                   djnz $2AAF            ; -> l_2AAF  {djnz l_2AAF}

;; if ( 0 == nestlr_inh  ||  0 != obj_pos_rel[0] )  ...
2ABD: 3A 24 98                ld   a,($9824)        ; {ld a,(ds_plyr_actv +_b_nestlr_inh)}
2AC0: A7                      and  a                
2AC1: 3A 00 99                ld   a,($9900)        ; {ld a,(ds_hpos_loc_offs + 0x00)} check for 0 i.e. returned to center
2AC4: 28 03                   jr   z,$2AC9          ; -> l_2AC9
2AC6: A7                      and  a                
2AC7: 28 11                   jr   z,$2ADA          ; -> l_2ADA_done  {jr z,l_2ADA_done}

;; ... then ...
;; if ( 32 == obj_pos_rel[0] )  then nest_dir_lr = 1
l_2AC9:
2AC9: FE 20                   cp   $20              
2ACB: 20 06                   jr   nz,$2AD3         ; -> l_2AD3
2ACD: 3E 01                   ld   a,$01            
2ACF: 32 0F 92                ld   ($920F),a        ; {ld (ds_9200_glbls + 0x0F),a} 1 ... nest direction... right limit reached
2AD2: C9                      ret                   

;; if ( -32 == obj_pos_rel[0] ) then nest_dir_lr = 0
l_2AD3:
2AD3: D6 E0                   sub  $E0              ; -$20
2AD5: C0                      ret  nz               
2AD6: 32 0F 92                ld   ($920F),a        ; {ld (ds_9200_glbls + 0x0F),a} 0 ... nest direction... left limit reached
2AD9: C9                      ret                   

;; the formation is complete... diving attacks shall commence
l_2ADA_done:
2ADA: AF                      xor  a                
2ADB: 32 0F 92                ld   ($920F),a        ; {ld (ds_9200_glbls + 0x0F),a} 0 ... nest direction
2ADE: 32 0A 90                ld   ($900A),a        ; {ld (ds_cpu0_task_actv + 0x0A),a} 0 ... disable this task (f_2A90)
2AE1: 3C                      inc  a                
2AE2: 32 A0 9A                ld   ($9AA0),a        ; [ds_9AA0: label for pointer+index operations] 1 ... sound-fx count/enable register, pulsing formation sound effect
2AE5: 32 09 90                ld   ($9009),a        ; {ld (ds_cpu0_task_actv + 0x09),a} 1 ... enable f_1DE6 ... collective bug movement
2AE8: C9                      ret                   

;; last bug of challenge is gone or killed
l_2AE9_done:
2AE9: 32 0A 90                ld   ($900A),a        ; {ld (ds_cpu0_task_actv + 0x0A),a} 0 ... disable this task (f_2A90)
2AEC: C9                      ret                   
