2AF5: FF FF FF FF FF FF FF FF .db   $FF,$FF,$FF,$FF,$FF,$FF,$FF,$FF  ; [rev B]
2AFD: FF FF FF FF FF FF FF FF .db   $FF,$FF,$FF,$FF,$FF,$FF,$FF,$FF  ; [rev B]
2B05: FF FF FF FF FF FF FF FF .db   $FF,$FF,$FF,$FF,$FF,$FF,$FF,$FF  ; [rev B]
2B0D: FF FF FF FF FF FF FF FF .db   $FF,$FF,$FF,$FF,$FF,$FF,$FF,$FF  ; [rev B]
2B15: FF FF FF FF FF FF FF FF .db   $FF,$FF,$FF,$FF,$FF,$FF,$FF,$FF  ; [rev B]
