;; new_stage.s:
;;  gg1-3.2m, 'maincpu' (Z80)
;; loads the new parameters for the game stages
;; .area ROM (ABS,OVR)
;; .org 0x2C00
;; stg_bombr_setparms()
;;  Description:
;;   new stage setup
;;   selects table based on level and difficulty setting, loads the new
;;   parameters for the stage
;; IN:
;;  ...
;; OUT:
;;  ...
c_2C00:
2C00: 3A 21 98                ld   a,($9821)        ; {ld a,(ds_plyr_actv +_b_stgctr)} new stage setup

;; while (A > 0x1B)  A -= 4
l_2C03:
2C03: FE 1B                   cp   $1B              
2C05: 38 04                   jr   c,$2C0B          ; -> l_2C0B  goto 2C0B
2C07: D6 04                   sub  $04              
2C09: 18 F8                   jr   $2C03            ; -> l_2C03

;; E = ( adj_stg_cnt - 1 ) + adj_stg_cnt * 4  ... multiply by 5
l_2C0B:
2C0B: 3D                      dec  a                
2C0C: 6F                      ld   l,a              
2C0D: 07                      rlca                  
2C0E: 07                      rlca                  
2C0F: 85                      add  a,l              
2C10: 5F                      ld   e,a              

;; pTbl = bmbr_stg_cfg_lut[mchn_cfg.rank]
2C11: 3A 84 99                ld   a,($9984)        ; {ld a,(b_mchn_cfg_rank)}
2C14: 21 65 2C                ld   hl,$2C65         ; {ld hl,#bmbr_stg_cfg_lut} ld the table of ptrs
2C17: CF                      rst  $08              ; HL += 2A
2C18: 7E                      ld   a,(hl)           
2C19: 23                      inc  hl               
2C1A: 66                      ld   h,(hl)           
2C1B: 6F                      ld   l,a              

;; pTbl[E];
2C1C: 7B                      ld   a,e              ; adj_stg_cnt * 5
2C1D: D7                      rst  $10              ; HL += A ... ofset into lut
2C1E: 11 C0 99                ld   de,$99C0         ; {ld de,#ds_new_stage_parms}
2C21: 06 05                   ld   b,$05            
l_2C23:
2C23: 7E                      ld   a,(hl)           
2C24: 4F                      ld   c,a              ; stash data byte

;; new_stage_parms[L * 2 + 0] = upper nibble
2C25: 07                      rlca                  
2C26: 07                      rlca                  
2C27: 07                      rlca                  
2C28: 07                      rlca                  
2C29: E6 0F                   and  $0F              
2C2B: 12                      ld   (de),a           

;; new_stage_parms[L * 2 + 1] = lower nibble
2C2C: 1C                      inc  e                
2C2D: 79                      ld   a,c              ; retrieve data byte
2C2E: E6 0F                   and  $0F              
2C30: 12                      ld   (de),a           

;; increment pointers
2C31: 1C                      inc  e                
2C32: 23                      inc  hl               
2C33: 10 EE                   djnz $2C23            ; -> l_2C23

;; set ds_new_stage_parms[0x0A] ... number of remaining aliens for enable clone-attack
2C35: 3A 21 98                ld   a,($9821)        ; {ld a,(ds_plyr_actv +_b_stgctr)} new stage setup

;; if ( stage_ctr < 3 )  A = 0 ...
2C38: FE 03                   cp   $03              
2C3A: 30 03                   jr   nc,$2C3F         ; -> l_2C3F

;; ... then
2C3C: AF                      xor  a                
2C3D: 18 07                   jr   $2C46            ; -> l_2C46

;; else if 0xFF == (plyr_state_actv.stage_ctr | 0x0FC)
l_2C3F:
2C3F: F6 FC                   or   $FC              ; challenge stages numbered so that bit_0 + bit_1 == 11b
2C41: 3C                      inc  a                
2C42: 28 02                   jr   z,$2C46          ; -> l_2C46

;; ... then
2C44: 3E 0A                   ld   a,$0A            ; non-challenge stage
l_2C46:
2C46: 12                      ld   (de),a           ; ds_new_stage_parms[$A]

;; 16 02 02 i.e. start of round defaults for yellow, red, boss bomber timers
2C47: 01 16 02                ld   bc,$0216         
2C4A: ED 43 C1 92             ld   ($92C1),bc       ; = $0216 (int values for ready timers of each bomber type)
2C4E: ED 43 C0 92             ld   ($92C0),bc       ; [b_92C0] = $0216 (int values for ready timers of each bomber type)

;; adjust star speed
;; A = (stage_ctr < $10) : stage_ctr ? $10
2C52: 3A 21 98                ld   a,($9821)        ; {ld a,(ds_plyr_actv +_b_stgctr)} limit is 10
2C55: FE 10                   cp   $10              
2C57: 38 02                   jr   c,$2C5B          ; -> l_2C5B
2C59: 3E 10                   ld   a,$10            
l_2C5B:
2C5B: 07                      rlca                  
2C5C: 07                      rlca                  
2C5D: E6 70                   and  $70              
2C5F: C6 40                   add  a,$40            
2C61: 32 BB 99                ld   ($99BB),a        ; {ld (ds_99B9_star_ctrl + 0x02),a}
2C64: C9                      ret                   

;; selected table is by difficulty (rank) configured by dip switch setting
bmbr_stg_cfg_lut:
2C65: EF 2C                   .db   $EF,$2C
2C67: 71 2D                   .db   $71,$2D
2C69: F3 2D                   .db   $F3,$2D
2C6B: 6D 2C                   .db   $6D,$2C

;; 26 stages of data: 4 sub-tables for the ranks, 5-bytes per stage (1 parameter per nibble)
