;; continue to '5TH' ...
;; c_3231()
;;  Description:
;;   Setting lines for hi-score table. 1st,2nd,3rd,and 4th are by calling the
;;   function. 5th is by allowing execution to fall through from c_puts_top5scores.
;;   Each call to 3270 offsets DE for the next column (-$20) and advanced HL.
;; IN:
;;  B=rank (1 to 5)
;; OUT:
;;  B+=1
c_3231:
3231: 78                      ld   a,b              ; B=rank (1 to 5)
3232: 3D                      dec  a                
3233: 87                      add  a,a              
3234: 87                      add  a,a              
3235: 87                      add  a,a              ; A=offset into table ... (B-1)*8
3236: 21 C5 32                ld   hl,$32C5         ; score placement characters: 'ST', 'ND', 'RD' etc.
3239: D7                      rst  $10              ; HL += A
323A: 5E                      ld   e,(hl)           ; destination lo-byte
323B: 23                      inc  hl               
323C: 56                      ld   d,(hl)           ; destination hi-byte
323D: 23                      inc  hl               
323E: 78                      ld   a,b              ; B=numerical score placement
323F: 12                      ld   (de),a           ; putc '5' of '5TH' on screen.
3240: CD 73 32                call $3273            ; -> c_3273  DE:-=$20
3243: CD 70 32                call $3270            ; -> c_3270  putc 'T' of '5TH' on screen.
3246: CD 70 32                call $3270            ; -> c_3270  putc 'H' of '5TH' on screen.
3249: CD 73 32                call $3273            ; -> c_3273  DE:-=$20
324C: CD 73 32                call $3273            ; -> c_3273  DE:-=$20
324F: 7E                      ld   a,(hl)           ; const ptr to score (lo-byte)
3250: 23                      inc  hl               
3251: 4E                      ld   c,(hl)           ; const ptr to score (lo-byte)
3252: 23                      inc  hl               
3253: E5                      push hl               ; save const ptr to player initials.
3254: 61                      ld   h,c              
3255: 6F                      ld   l,a              ; HL=ptr to 6-bytes score text
3256: CD 75 32                call $3275            ; -> c_3275  puts 'XXXXX' of 5th place on screen.
3259: 7B                      ld   a,e              
325A: D6 C0                   sub  $C0              ; advance column ptr right 6 characters.
325C: 5F                      ld   e,a              
325D: 30 01                   jr   nc,$3260         ; -> l_3260
325F: 15                      dec  d                ; when not jr?
l_3260:
3260: E1                      pop  hl               
3261: 7E                      ld   a,(hl)           
3262: 23                      inc  hl               
3263: 66                      ld   h,(hl)           
3264: 6F                      ld   l,a              
3265: CD 70 32                call $3270            ; -> c_3270  putc 1st initial
3268: CD 70 32                call $3270            ; -> c_3270  putc 2nd initial
326B: CD 70 32                call $3270            ; -> c_3270  putc 3rd initial
326E: 04                      inc  b                
326F: C9                      ret                   

