;;   checks credits available and exits early if credits are available.
;; IN:
;;  ...
;; OUT:
;;  ...
;; if (free-play)
c_32ED_top5_dlg_endproc:
32ED: 3A B5 99                ld   a,($99B5)        ; {ld a,(ds3_99B5_io_input + 0x00)} io_input[credit_count]
32F0: FE A0                   cp   $A0              
32F2: 28 07                   jr   z,$32FB          ; -> l_32FB_check_for_timeout  {jr z,l_32FB_check_for_timeout}

;; else if ( hw credit cnt > current credit count ) goto finish
32F4: 47                      ld   b,a              
32F5: 3A B8 99                ld   a,($99B8)        ; {ld a,(b8_99B8_credit_cnt)}
32F8: B8                      cp   b                
32F9: 38 05                   jr   c,$3300          ; -> l_3300_finish  {jr c,l_3300_finish}
l_32FB_check_for_timeout:
32FB: 3A AE 92                ld   a,($92AE)        ; {ld a,(ds4_game_tmrs + 2)}
32FE: A7                      and  a                
32FF: C0                      ret  nz               

;; Time up. Copy available characters from input to Top 5 score name table.
;; The pop forces 1 stack frame to be skipped (returns to caller of _top5_dlg_proc)
l_3300_finish:
3300: E1                      pop  hl               

;; Setup HL and DE as pointers for copy from input characters to new Top5 table name entry.
3301: 26 81                   ld   h,$81            ; {ld h,#>m_tile_ram + >0x0100}
3303: 3A 10 8A                ld   a,($8A10)        ; [$8A10: lower byte of current input character's address in v-ram] lower byte of current character's address in v-ram
3306: 6F                      ld   l,a              
3307: ED 5B 04 8A             ld   de,($8A04)       ; [$8A04: pointer to new name in table] pointer to next name character to store in Top 5 table...
330B: 13                      inc  de               ; ... actually it points to ( next_character - 1 )

;; When the time runs out, 1, 2, or 3 characters may have already been selected
;; by the player. Rather than keeping count, it simply checks that the column
;; pointer from the input is off past the right limit. The rightmost input
;; character is $8109 and will underflow when subtracting $20. Since the
;; subtraction is done by addition (-21h == $DF), the inverse of the Cy flag can
;; be used to detect the equivalent of the underflow of the subtraction.
l_330C:
330C: ED A0                   ldi                   
330E: 3E DF                   ld   a,$DF            ; subtract $21 since the LDI added 1 to HL
3310: 25                      dec  h                
3311: 85                      add  a,l              
3312: 30 01                   jr   nc,$3315         ; -> l_3315
3314: 24                      inc  h                ; L is 9, 29, or 49 so Cy is set, and we restor the  H...
l_3315:
3315: 6F                      ld   l,a              
3316: CB 44                   bit  0,h              ; if the Cy was set, then bit 0 should be set.
3318: 20 F2                   jr   nz,$330C         ; -> l_330C
331A: C9                      ret                   

