;; c_rom_test_csum_calc()
;;  Description:
;;   C is set to $00 by the caller, indicating the expected checksum
;;   result. Adding the last byte of each rom section results in a 0 checksum.
;; IN:
;;  ...
;; OUT:
;;  ...
c_rom_test_csum_calc:   ; galagao $3521
352B: E5                      push hl               
352C: EB                      ex   de,hl            ; Swap the starting address from DE to HL.
352D: 16 10                   ld   d,$10            ; Set the MSB of the number of bytes to be summed ($1000)
352F: AF                      xor  a                ; A==$00
3530: 47                      ld   b,a              ; B==$00, so we now have BC==00. The first dec will roll

;; thru to $FF, giving an effective count of $100.
l_3527:   ; galagao $3527
3531: 86                      add  a,(hl)           ; Begin the checksum loop, with start address now in HL
3532: 32 30 68                ld   ($6830),a        ; {ld (_sfr_watchdog),a}
3535: 23                      inc  hl               
3536: 10 F9                   djnz $3531            ; -> l_3527  CPU 1 & CPU 2 kick in around the time this is first called
3538: 15                      dec  d                
3539: 20 F6                   jr   nz,$3531         ; -> l_3527  The MSB of the repeat count is the outer loop count.
353B: EB                      ex   de,hl            
353C: E1                      pop  hl               
353D: B9                      cp   c                ; final sum must be $00
353E: C8                      ret  z                ; end 'call c_rom_test_csum_calc'

