;;  ROM test status flags:
;;  $9100 = 0  CPU-sub rom test status, pause/resume (and returns test result)
;;  $9101 = 0  CPU-sub2 rom test status, pause/resume (and returns test result)
;;  $9102      CPU0 test state: 1->$0000, 2->$1000 ... 4->$3000 $FF->CPU0 ROM test complete
;;             Error code, failed ROM test (either sub CPU), passed as parameter to subroutine.
;; IN:
;;  ...
;; OUT:
;;  ...
j_romtest_ng:   ; galagao $3535
353F: 21 95 3B                ld   hl,$3B95         ; {ld hl,#str_3B88}
3542: CD 1B 33                call $331B            ; -> c_text_out  {call c_text_out}
3545: 11 44 82                ld   de,$8244         ; {ld de,#m_tile_ram + 0x0240 + 0x04}
3548: 21 02 91                ld   hl,$9102         ; {ld hl,#ds_rom_test_status + 0x02} load error code
354B: AF                      xor  a                
354C: ED 6F                   rld                   ; rld  (hl)
354E: 12                      ld   (de),a           
354F: E7                      rst  $20              ; DE-=$20
3550: AF                      xor  a                
3551: ED 6F                   rld                   ; rld  (hl)
3553: 12                      ld   (de),a           
