;; j_Test_menu_proc()
;;  Description:
;;   Process runner for test menu selection.
;;   If the svc switch is NOT set, it simply continues to Machine Init.
;; IN:
;;  ...
;; OUT:
;;  ...
;; TODO: put the PORT defintions from MAME in here somewhere as reference
;; e.g.
;;   PORT_SERVICE( 0x08, IP_ACTIVE_LOW )
;; IO Input Registers for "switch" mode
;;   [0] test switch & credits in
;;       $7D fire 2
;;       $7E fire 1
;;       $7B 1 start
;;       $77 2 start
;;       $6F coin 1
;;       $5F coin 2
;;       $3F 'service 1' (99999999)
;;   [1] control panel 1
;;       $F7 (L)
;;       $FD (R)
;;   [2] control panel 2 (table-top cabinet cfg)
;;       $7F (L)
;;       $DF (R)
;; synchronize with next frame transition.
;; prev_frame_cts[0] = frame_cts[0]
j_Test_menu_proc:   ; galagao $3620
362A: 3A A0 92                ld   a,($92A0)        ; {ld a,(ds3_92A0_frame_cts + 0)} Get t0.
362D: 4F                      ld   c,a              

;; while ( frame_cts[0] == prev_frame_cts[0] )
l_3624:   ; galagao $3624
362E: 3A A0 92                ld   a,($92A0)        ; {ld a,(ds3_92A0_frame_cts + 0)} Get t1.
3631: B9                      cp   c                
3632: 28 FA                   jr   z,$362E          ; -> l_3624

;; 9110-9116 used as temp array to capture/debounce successive input states.
3634: 21 16 91                ld   hl,$9116         ; {ld hl,#(b_svc_test_inp_buf + 0x06)}
3637: 11 17 91                ld   de,$9117         ; {ld de,#(b_svc_test_inp_buf + 0x07)}
363A: 01 07 00                ld   bc,$0007         
363D: ED B8                   lddr                  ; (9117):=(9116) etc. etc.

;; HL==910F, DE==9110
363F: EB                      ex   de,hl            ; HL:=9110  ( debounce[0] )

;; (3636)
;; if ( IN0H_8 == INACTIVE ) goto Machine_init
3640: 11 B5 99                ld   de,$99B5         ; {ld de,#(ds3_99B5_io_input + 0x00)}
3643: 1A                      ld   a,(de)           
3644: CB 7F                   bit  7,a              ; ACTIVE_LOW i.e. if bit_7==1 switch is off
3646: C2 C4 36                jp   nz,$36C4         ; -> j_36BA_Machine_init  {jp nz,j_36BA_Machine_init}

;; Read IN0 (button conditions) into B
3649: 77                      ld   (hl),a           ; save new input value to debounce[0]
364A: 23                      inc  hl               
364B: B6                      or   (hl)             ; Trigger on input received now t(0) or t(-1) ...
364C: 23                      inc  hl               
364D: 2F                      cpl                   ; A:=~A (1's compl.)
364E: A6                      and  (hl)             ; Input stimulus is new if not active at t(-2)
364F: 23                      inc  hl               
3650: A6                      and  (hl)             ; Checking against saved condition of last frame...
3651: 77                      ld   (hl),a           ; ... and save the input condition this frame.
3652: 47                      ld   b,a              ; stash the button condition in B for now...

;; Read IN1 (stick conditions) into B
3653: 23                      inc  hl               ; HL:=9114
3654: 13                      inc  de               ; DE:=99b6  (stick input from IN1)
3655: 1A                      ld   a,(de)           
3656: 77                      ld   (hl),a           ; save new input value to debounce[4]
3657: 23                      inc  hl               
3658: B6                      or   (hl)             ; or t(-1) value
3659: 23                      inc  hl               
365A: 2F                      cpl                   
365B: A6                      and  (hl)             ; not t(-2)
365C: 23                      inc  hl               
365D: A6                      and  (hl)             ; and t(-1) condition
365E: 77                      ld   (hl),a           ; ... and save the input condition this frame.
365F: 6F                      ld   l,a              ; grab the stick condition
3660: 60                      ld   h,b              ; grab button condition from B

;; active low input states are now inverted in HL.
;; Successive left shifts (into Cy) with the countdown in B indicate the active input.
3661: 06 10                   ld   b,$10            ; counter...

;; for ( B==16; B>0; B-- ) { if (bit_set) call input_hdlr }
l_3659:   ; galagao $3659
3663: 29                      add  hl,hl            ; does left shift (into Cy)
3664: DC E0 39                call c,$39E0          ; -> c_svc_test_input_hdlr  {call c,c_svc_test_input_hdlr}
3667: 10 FA                   djnz $3663            ; -> l_3659
3669: CD FE 37                call $37FE            ; -> _l_37F4  {call c_svc_updt_dsply} this also flips the screen back to "normal"

;; Check timer to erase Machine Totals info.
;; First time here, timer register contains stray data from tests and is
;; not specifically initialized. Resulting countdown time about 14 minutes...
;; Timer is reset to 15 seconds after data is displayed the first time..
;; if ( 15sec_tmr == 0 ) goto 3672
366C: 2A 72 92                ld   hl,($9272)       ; {ld hl,(w_svc_15sec_tmr)} lsb first)
366F: 7C                      ld   a,h              
3670: B5                      or   l                
3671: 28 09                   jr   z,$367C          ; -> l_3672

