3801: 1F                      rra                   ; get DSWA#8 (sfr_dsw8:1)

;; inverting the bit provides the index
3802: 3C                      inc  a                ; invert bit in bit-0
3803: E6 01                   and  $01              
3805: 32 83 99                ld   ($9983),a        ; {ld (b_mchn_cfg_cab_type),a}

;; svc_cab_type( a )
3808: 21 D6 3A                ld   hl,$3AD6         ; {ld hl,#str_3ACC} 0-"UPRIGHT", 1-"TABLE"
380B: CF                      rst  $08              ; HL += 2A
380C: CD 6B 3A                call $3A6B            ; -> c_svc_cab_type  {call c_svc_cab_type}

