;; Bonus Ships Awarded (DSWB)
;; Mask  Selection    S#4 S#5 S#6    Index into table 3AA4
;; 0x20  20-60-60     ON  ON  OFF    1
;; 0x10  20-70-70     ON  OFF ON     2
;; 0x30  20-80-80     ON  OFF OFF    3
;; 0x08  30-100-100   OFF ON  ON     4
;; 0x28  30-120-120   OFF ON  OFF    5
;; 0x18  20-60        OFF OFF ON     6
;; 0x38  30-80        OFF OFF OFF    7
;; 0x00  None         ON  ON  ON     0
;; Bonus config displayed in following format:
;; 1ST BONUS  X0000 PTS
;; 2ND BONUS XX0000 PTS
;; AND EVERY XX0000 PTS
l_38AB:   ; galagao $38AB
38B5: 21 03 68                ld   hl,$6803         ; {ld hl,#_sfr_dsw4} bonus levels
38B8: 06 03                   ld   b,$03            ; 3 positions to read
38BA: AF                      xor  a                
l_38B1:   ; galagao $38B1
38BB: 4E                      ld   c,(hl)           
38BC: CB 19                   rr   c                ; "right-shift" lo-bit into Cy flag.
38BE: 8F                      adc  a,a              ; "left-shift" the hi-bit and add the lo-bit from Cy flag.
38BF: 23                      inc  hl               
38C0: 10 F9                   djnz $38BB            ; -> l_38B1

;; if ( 0 == switch_selection ) goto 392D  // display "BONUS NOTHING", ret to 35be
38C2: E6 07                   and  $07              
38C4: CA 37 39                jp   z,$3937          ; -> l_392D
38C7: 4F                      ld   c,a              
38C8: 3A 82 99                ld   a,($9982)        ; {ld a,(b_mchn_cfg_nships)} Bonus levels depend upon number of fighters starting.
38CB: E6 04                   and  $04              ; note: num_ships = mchn_cfg_nships + 1
38CD: 87                      add  a,a              
38CE: 81                      add  a,c              ; add dsw value
38CF: 87                      add  a,a              ; a:=a*2 ... use as offset into table
38D0: 21 AE 3A                ld   hl,$3AAE         ; {ld hl,#str_3AA4} bonus config data
38D3: D7                      rst  $10              ; HL += A...A==2,C,4,6,E,8,A
38D4: 11 80 99                ld   de,$9980         ; {ld de,#w_mchn_cfg_bonus} ld two-bytes (str_3AA4)
38D7: ED A0                   ldi                   
38D9: ED A0                   ldi                   
38DB: 2B                      dec  hl               ; point to second byte of two-byte Table entry
38DC: 0E 01                   ld   c,$01            ; flag tells 38DA that it was 'called' i.e. get out by return
38DE: CD E4 38                call $38E4            ; -> c_38DA  display 'second and every' bonus settings
38E1: 2B                      dec  hl               ; point to first byte of two-byte table entry
38E2: 0E 00                   ld   c,$00            ; flag allows 3904 ret to occur

;; c_38DA()
;;  Description:
;; IN:
;;  ...
;; OUT:
;;  ...
c_38DA:   ; galagao $38DA
38E4: 7E                      ld   a,(hl)           ; ld one byte from the two-byte table entry
38E5: 3C                      inc  a                ; setup test for $FF in the bonus-none parameters
38E6: CA 45 39                jp   z,$3945          ; -> l_393B  if 'bonus none', skip the 'second and every' display (when?)
38E9: 79                      ld   a,c              ; first-pass (second-and-every) indicated by 1, second-pass indicated by 0..
38EA: 87                      add  a,a              ; ...so A==2 or A==0  (offset from 3B1A to string address loaded into HL)
38EB: E5                      push hl               ; save address of table-entry
38EC: 21 27 3B                ld   hl,$3B27         ; {ld hl,#str_3B1A} i.e., 1E 3B "1ST BONUS ", 36 3B "2ND BONUS"
38EF: D7                      rst  $10              ; HL += A                                  ; HL += A
38F0: 7E                      ld   a,(hl)           ; get LSB of src address
38F1: 23                      inc  hl               
38F2: 66                      ld   h,(hl)           ; get MSB of src address
38F3: 6F                      ld   l,a              ; ld LSB to L
38F4: C5                      push bc               ; C holds the so-called 'first-bonus/second-bonus' flag, save it!
38F5: CD 1B 33                call $331B            ; -> c_text_out  {call c_text_out} display "2ND BONUS" or "1ST BONUS"
38F8: CD 1B 33                call $331B            ; -> c_text_out  {call c_text_out} display "0000 PTS" of "??? BONUS XX0000 PTS"...

;; HL==$3B2B or HL==$3B42, as there are two copies of "0000 PTS"
;; DE==$80B2, that value will be used later......?
38FB: C1                      pop  bc               ; get back the first-pass-second-pass flag
38FC: E1                      pop  hl               ; get back the address of the table-entry
38FD: 7E                      ld   a,(hl)           ; ld the table-entry...
38FE: E6 7F                   and  $7F              ; ... and mask out bit-7 which indicates there is no 'and-every' setting
3900: EB                      ex   de,hl            ; save address of table-entry in HL... DE==$80B2 (address of ' ' in "PTS ")
3901: 21 F0 81                ld   hl,$81F0         ; {ld hl,#m_tile_ram + 0x01E0 + 0x10}
3904: 41                      ld   b,c              ; the first time through here, C==1...
3905: 10 02                   djnz $3909            ; -> l_38FF  ... so the second time, when the Flag is 0 we skip next two lines
3907: 23                      inc  hl               
3908: 23                      inc  hl               ; ...now down 2 rows from $81F0 i.e. address of 'X' in "2ND BONUS X 0000 PTS"
l_38FF:   ; galagao $38FF
3909: CD 28 39                call $3928            ; -> c_391E  display "X" of "??? BONUS XX0000 PTS"
390C: EB                      ex   de,hl            ; HL:= to second-or-first-table-entry again
390D: 0D                      dec  c                ; C:=$00 at end of first-pass...
390E: C0                      ret  nz               ; ...after second-pass, ret to _35BE, end 'call _37F4' (displaying dsw menu)
390F: EB                      ex   de,hl            ; save the current bonus-parameter-table-entry into DE
3910: 1A                      ld   a,(de)           ; A:=$86 for 20-60 setting, the second of the two byte-parameters
3911: CB 7F                   bit  7,a              ; if (bit-7)...
3913: C2 53 39                jp   nz,$3953         ; -> l_3949  ... then jp (bit test is Z flag... bit-7 set if no 'and-every' bonus)
3916: 21 F4 81                ld   hl,$81F4         ; {ld hl,#m_tile_ram + 0x01E0 + 0x14} address of character X in "AND EVERY X 0000 PTS"
3919: CD 28 39                call $3928            ; -> c_391E  display XX of "AND EVERY XX0000 PTS"
391C: D5                      push de               
391D: 21 5A 3B                ld   hl,$3B5A         ; {ld hl,#str_3B4D} "AND EVERY"
3920: CD 1B 33                call $331B            ; -> c_text_out  {call c_text_out}
3923: CD 1B 33                call $331B            ; -> c_text_out  {call c_text_out} display "0000 PTS" of "AND EVERY XX0000 PTS"  ( HL expected to be $3B59)
3926: E1                      pop  hl               
3927: C9                      ret                   

;; end 'call 38DA', ret to _38D7
;; c_391E()
;;  Description:
;;   converts bonus levels to decimal and display on screen
;;   on entry, HL==address_to_write_to
;; A==value from bonus-parameter-table
