c_391E:   ; galagao $391E
3928: FE 0A                   cp   $0A              ; check if value if > 10
392A: 06 24                   ld   b,$24            ; start with a ' ' (space) character in B
392C: 38 04                   jr   c,$3932          ; -> l_3928  if Cy, it means that A<$0A, so jr past the display of the 10's place digit
392E: 06 01                   ld   b,$01            ; value is 10 or greater...
3930: D6 0A                   sub  $0A              ; ...so subtract off the value of 10...
l_3928:   ; galagao $3928
