;; c_svc_machine_totals()
;;  Description:
;;   Show "remaining" counts of Games Played and Points Scored, in this format:
;;   'XX.XYYY.YYYY.ZZZZ.ZAAA.'
;;   The indicators are subtracted from their maximum...
;;    i.e. 999-UUU=XXX or 9999999-UUUUUUU=YYYYYYY
;;   XXX:     b16_99E0_ttl_plays_bcd  (lower 3 BCD nibbles only i.e. 0-999)
;;   YYYYYYY: b32_99E2_sum_score_bcd  (lower 3 BCD nibbles only i.e. 0-999)
;;   ZZZZZ:   b32_99E6_gametime_secs_bcd (5 BCD digits of seconds count ...
;;            ... omit the 1/60th count)
;;   AAA:     b16_99EA_bonus_ct_bcd  (lower 3 BCD nibbles only i.e. 0-999)
;; IN:
;;  ...
;; OUT:
;;  ...
;; NOTE: the game time and bonus count would only be non-zero if the machine is
;;       warm reset during a running game. MAME (136) doesn't seem to handle
;;       warm reset properly and it hangs at "RAM OK".
c_svc_machine_totals:   ; galagao $397D
3987: 21 E0 99                ld   hl,$99E0         ; {ld hl,#b16_99E0_ttl_plays_bcd}
398A: 11 5E 83                ld   de,$835E         ; {ld de,#m_tile_ram + 0x0340 + 0x1E} at lower left of screen

;; the first set has 2 digits, followed by the '.'
398D: 0E 02                   ld   c,$02            
398F: 06 01                   ld   b,$01            
3991: CD A1 39                call $39A1            ; -> c_3997  XX.X
3994: 06 03                   ld   b,$03            
3996: CD A1 39                call $39A1            ; -> c_3997  ____YYY.YYYY
3999: 06 02                   ld   b,$02            
399B: CD A1 39                call $39A1            ; -> c_3997  HL=99E6
399E: 23                      inc  hl               ; skip 1/60th part of timer.
399F: 06 01                   ld   b,$01            

;; 3997 again ("inline")... do the bonus-count portion ("AAA")
;; c_3997()
;;  Description:
;; IN:
;;  ...
;; OUT:
;;  ...
c_3997:   ; galagao $3997
39A1: CD B4 39                call $39B4            ; -> c_39AA
l_399A:   ; galagao $399A
39A4: CD AA 39                call $39AA            ; -> c_39A0  does 39AA also
39A7: 10 FB                   djnz $39A4            ; -> l_399A
39A9: C9                      ret                   

;; c_39A0()
;;  Description:
;; IN:
;;  ...
;; OUT:
;;  ...
c_39A0:   ; galagao $39A0
39AA: 3E 99                   ld   a,$99            
39AC: 96                      sub  (hl)             
39AD: 1F                      rra                   
39AE: 1F                      rra                   
39AF: 1F                      rra                   
39B0: 1F                      rra                   
39B1: CD B8 39                call $39B8            ; -> c_39AE

