;; c_svc_cab_type()
;;  Description:
;;   wrapper for c_text_out (dereferences the pointer passed in HL)
;;   (caller is displaying the cab-type)
;; IN:
;;  ...
;; OUT:
;;  ...
c_svc_cab_type:   ; galagao $3A61
3A6B: 7E                      ld   a,(hl)           ; LSB
3A6C: 23                      inc  hl               
3A6D: 66                      ld   h,(hl)           ; MSB
